import { DurableObject } from "cloudflare:workers";


/* Arquivo único: o site inteiro (SITE) + o servidor das salas (Sala). */

/* Roteador: /ws/CODIGO abre a sala em tempo real; qualquer outro endereço mostra o site (index.html). */
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const m = url.pathname.match(/^\/ws\/([A-Z0-9]{4})$/);
    if (m) {
      if (request.headers.get("Upgrade") !== "websocket") {
        return new Response("Esta rota aceita apenas WebSocket.", { status: 426 });
      }
      const sala = env.SALAS.get(env.SALAS.idFromName(m[1]));
      return sala.fetch(request);
    }
    return new Response(SITE, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
  }
};

/* Limpa a presença que cada pessoa envia: só campos conhecidos, com tamanho limitado. */
function limpar(p) {
  if (!p || typeof p !== "object") return {};
  const out = {};
  const str = (v, max) => (typeof v === "string" ? v.slice(0, max) : undefined);
  if (p.role === "host" || p.role === "member") out.role = p.role;
  if (str(p.name, 24)) out.name = str(p.name, 24);
  if (typeof p.since === "number" && isFinite(p.since)) out.since = p.since;
  if (str(p.topic, 12)) out.topic = str(p.topic, 12);
  if (str(p.qid, 6)) out.qid = str(p.qid, 6);
  if (Array.isArray(p.order) && p.order.length <= 6 && p.order.every(Number.isInteger)) out.order = p.order;
  if (p.phase === "q" || p.phase === "rev") out.phase = p.phase;
  if (p.ans && typeof p.ans === "object" && str(p.ans.q, 6) && Number.isInteger(p.ans.c)) out.ans = { q: p.ans.q.slice(0, 6), c: p.ans.c };
  return out;
}

/* Uma Sala por código. Usa hibernação: não gasta nada enquanto ninguém manda mensagem. */
export class Sala extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    // Responde "ping" com "pong" sem acordar a sala (mantém a conexão viva de graça)
    this.ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair("ping", "pong"));
  }

  async fetch() {
    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    const peer = crypto.randomUUID().replace(/-/g, "").slice(0, 10);
    this.ctx.acceptWebSocket(server);
    server.serializeAttachment({ peer, presence: {} });
    server.send(JSON.stringify({ t: "hello", peer, peers: this.lista() }));
    return new Response(null, { status: 101, webSocket: client });
  }

  lista(excluir) {
    return this.ctx.getWebSockets()
      .filter(ws => ws !== excluir && ws.readyState === 1)
      .map(ws => ws.deserializeAttachment())
      .filter(a => a && a.presence && Object.keys(a.presence).length);
  }

  avisarTodos(excluir) {
    const msg = JSON.stringify({ t: "peers", peers: this.lista(excluir) });
    for (const ws of this.ctx.getWebSockets()) {
      if (ws === excluir) continue;
      try { ws.send(msg); } catch (e) { /* conexão fechando */ }
    }
  }

  async webSocketMessage(ws, data) {
    if (typeof data !== "string" || data.length > 4096) return;
    let m;
    try { m = JSON.parse(data); } catch { return; }
    if (m && m.t === "presence") {
      const a = ws.deserializeAttachment() || {};
      a.presence = limpar(m.p);
      ws.serializeAttachment(a);
      this.avisarTodos();
    }
  }

  async webSocketClose(ws, code) {
    try { ws.close(code === 1005 ? 1000 : code, "saiu"); } catch (e) {}
    this.avisarTodos(ws);
  }

  async webSocketError(ws) {
    this.avisarTodos(ws);
  }
}

/* ===== O SITE (index.html inteiro, guardado como texto) ===== */
const SITE = "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Patologia Geral N1: banco de questões</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Literata:opsz,wght@7..72,400;7..72,600;7..72,700&family=Figtree:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F3F1F8; --card:#FFFFFF; --ink:#221C33; --muted:#655E7A; --line:#DCD6E8;\n  --hema:#3D2C74; --hema-soft:#E6E1F3; --eosin:#C93C74; --eosin-soft:#F8DDE8;\n  --frost:#ECE8F4; --frost2:#E2DCEE;\n  --ok:#1C7E60; --ok-soft:#DCF0E8; --bad:#B8373A; --bad-soft:#F7E0E0;\n  --serif:\"Literata\", Georgia, \"Times New Roman\", serif;\n  --sans:\"Figtree\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#16121F; --card:#211B2E; --ink:#EDE8F7; --muted:#A79FBD; --line:#3A3250;\n    --hema:#B6A6F0; --hema-soft:#2E2647; --eosin:#F07AA8; --eosin-soft:#43243A;\n    --frost:#2A2339; --frost2:#241E33;\n    --ok:#5FD1A8; --ok-soft:#173A30; --bad:#F28B8B; --bad-soft:#44222A;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#16121F; --card:#211B2E; --ink:#EDE8F7; --muted:#A79FBD; --line:#3A3250;\n  --hema:#B6A6F0; --hema-soft:#2E2647; --eosin:#F07AA8; --eosin-soft:#43243A;\n  --frost:#2A2339; --frost2:#241E33;\n  --ok:#5FD1A8; --ok-soft:#173A30; --bad:#F28B8B; --bad-soft:#44222A;\n}\n:root{box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px);}\n*,*::before,*::after{box-sizing:inherit;}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.5;-webkit-font-smoothing:antialiased;}\nbutton{font:inherit;color:inherit;}\n:focus-visible{outline:3px solid var(--eosin);outline-offset:2px;}\n.wrap{max-width:760px;margin:0 auto;padding:28px 18px 60px;}\nh1,h2,h3{font-family:var(--serif);font-weight:700;line-height:1.2;margin:0;}\n\n/* ---------- Home ---------- */\n.intro h1{font-size:clamp(1.9rem,5vw,2.6rem);letter-spacing:-0.01em;color:var(--hema);}\n.intro p{color:var(--muted);margin:10px 0 0;max-width:60ch;}\n.how{margin:22px 0 30px;padding:14px 16px;border-left:3px solid var(--eosin);background:var(--card);border-radius:0 8px 8px 0;font-size:.95rem;color:var(--muted);}\n.how strong{color:var(--ink);font-weight:600;}\n\n.slides{display:flex;flex-direction:column;gap:18px;}\n.slide{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);width:100%;min-height:168px;padding:0;border:1px solid var(--line);border-radius:6px;background:var(--card);cursor:pointer;text-align:left;overflow:hidden;box-shadow:0 1px 0 var(--line), 0 10px 24px -18px rgba(61,44,116,.45);transition:transform .15s ease, box-shadow .15s ease;}\n.slide:hover{transform:translateY(-2px);box-shadow:0 1px 0 var(--line), 0 16px 30px -18px rgba(61,44,116,.55);}\n.slide .label{padding:16px 16px 14px;background:repeating-linear-gradient(135deg,var(--frost) 0 3px,var(--frost2) 3px 6px);border-right:1px solid var(--line);display:flex;flex-direction:column;justify-content:space-between;gap:14px;}\n.slide .label h2{font-size:1.2rem;color:var(--ink);}\n.slide .label .total{font-size:.85rem;color:var(--muted);margin-top:4px;}\n.stats{display:flex;gap:14px;flex-wrap:wrap;}\n.stat{display:flex;flex-direction:column;line-height:1.15;}\n.stat b{font-size:1.25rem;font-family:var(--serif);}\n.stat span{font-size:.78rem;color:var(--muted);}\n.stat.due b{color:var(--eosin);}\n.stat.new b{color:var(--hema);}\n.stat.ok b{color:var(--ok);}\n.slide .glass{position:relative;display:flex;align-items:center;justify-content:center;padding:14px;}\n.tissue{width:min(150px,80%);aspect-ratio:1.35;opacity:.95;}\n.slide .go{position:absolute;right:12px;bottom:10px;font-size:.85rem;font-weight:600;color:var(--hema);}\n.slide.all{min-height:0;grid-template-columns:1fr;}\n.slide.all .label{border-right:0;flex-direction:row;align-items:center;justify-content:space-between;flex-wrap:wrap;}\n.footer{margin-top:36px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;font-size:.85rem;color:var(--muted);}\n.linkbtn{background:none;border:0;padding:6px 0;color:var(--muted);text-decoration:underline;cursor:pointer;}\n.linkbtn:hover{color:var(--bad);}\n\n/* ---------- Study ---------- */\n.topbar{display:flex;align-items:center;gap:12px;margin-bottom:10px;}\n.back{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:6px 12px;cursor:pointer;font-weight:500;}\n.topbar .t{flex:1;min-width:0;}\n.topbar .t h3{font-size:1rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.topbar .t div{font-size:.82rem;color:var(--muted);}\n.bar{height:6px;background:var(--line);border-radius:6px;overflow:hidden;margin-bottom:22px;}\n.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--hema),var(--eosin));width:0;transition:width .3s ease;}\n.qcard{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:22px 20px;}\n.src{font-size:.8rem;color:var(--muted);margin-bottom:10px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;}\n.src .tag{color:var(--eosin);font-weight:600;}\n.qtext{font-family:var(--serif);font-size:1.18rem;line-height:1.55;margin:0 0 18px;}\n.opts{display:flex;flex-direction:column;gap:10px;}\n.opt{display:grid;grid-template-columns:34px 1fr;gap:10px;align-items:start;width:100%;text-align:left;padding:12px 14px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);cursor:pointer;line-height:1.45;transition:border-color .12s ease, background .12s ease;}\n.opt:hover:not(:disabled){border-color:var(--hema);}\n.opt .l{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:.9rem;background:var(--hema-soft);color:var(--hema);}\n.opt:disabled{cursor:default;}\n.opt.right{border-color:var(--ok);background:var(--ok-soft);}\n.opt.right .l{background:var(--ok);color:#fff;}\n.opt.wrong{border-color:var(--bad);background:var(--bad-soft);}\n.opt.wrong .l{background:var(--bad);color:#fff;}\n.opt.dim{color:var(--muted);}\n.why{display:block;margin-top:6px;font-size:.86rem;line-height:1.45;color:var(--muted);}\n.opt.wrong .why{color:var(--bad);}\n.why b{font-weight:700;}\n.eh,.th{font-size:.76rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;margin-bottom:4px;}\n.eh{color:var(--hema);}\n.tip{margin-top:10px;padding:12px 14px;border-radius:8px;background:var(--eosin-soft);border-left:3px solid var(--eosin);font-size:.96rem;}\n.tip .th{color:var(--eosin);}\n.fb{margin-top:18px;}\n.verdict{font-family:var(--serif);font-size:1.25rem;font-weight:700;margin-bottom:6px;}\n.verdict.ok{color:var(--ok);}\n.verdict.no{color:var(--bad);}\n.expl{background:var(--bg);border-radius:8px;padding:12px 14px;font-size:.97rem;}\n.rate{margin-top:16px;}\n.rate p{margin:0 0 8px;font-size:.9rem;color:var(--muted);}\n.rbtns{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}\n.rbtn{border:1.5px solid var(--line);background:var(--card);border-radius:8px;padding:10px 6px;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:2px;font-weight:600;}\n.rbtn small{font-weight:400;color:var(--muted);font-size:.8rem;}\n.rbtn.hard:hover{border-color:var(--bad);}\n.rbtn.good:hover{border-color:var(--hema);}\n.rbtn.easy:hover{border-color:var(--ok);}\n.primary{display:block;width:100%;margin-top:16px;padding:12px;border:0;border-radius:8px;background:var(--hema);color:var(--card);font-weight:600;cursor:pointer;}\n.keys{margin-top:14px;font-size:.78rem;color:var(--muted);text-align:center;}\n.keys kbd{font-family:var(--sans);border:1px solid var(--line);border-bottom-width:2px;border-radius:4px;padding:0 5px;background:var(--card);}\n\n/* ---------- End / empty ---------- */\n.done{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:28px 22px;text-align:center;}\n.done h2{font-size:1.6rem;color:var(--hema);margin-bottom:8px;}\n.done p{color:var(--muted);margin:6px 0;}\n.score{display:flex;justify-content:center;gap:28px;margin:18px 0 6px;}\n.score div{display:flex;flex-direction:column;}\n.score b{font-family:var(--serif);font-size:2rem;}\n.score .a b{color:var(--ok);} .score .e b{color:var(--bad);}\n.score span{font-size:.82rem;color:var(--muted);}\n.row{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:18px;}\n.ghost{padding:11px 18px;border:1.5px solid var(--line);border-radius:8px;background:var(--card);cursor:pointer;font-weight:600;}\n.row .primary{width:auto;margin:0;padding:11px 18px;}\n\n/* ---------- Modo em grupo ---------- */\n.group-entry{display:flex;align-items:center;gap:14px;width:100%;margin:0 0 18px;padding:16px;border:1.5px solid var(--hema);border-radius:10px;background:linear-gradient(100deg,var(--hema-soft),var(--card));cursor:pointer;text-align:left;}\n.group-entry:disabled{cursor:default;border-color:var(--line);opacity:.8;}\n.group-entry .gi{flex-shrink:0;display:flex;}\n.group-entry .gi i{width:22px;height:22px;border-radius:50%;border:2px solid var(--card);background:var(--eosin);margin-left:-7px;}\n.group-entry .gi i:first-child{margin-left:0;background:var(--hema);}\n.group-entry .gi i:last-child{background:var(--ok);}\n.group-entry h2{font-size:1.1rem;color:var(--hema);}\n.group-entry p{margin:2px 0 0;font-size:.86rem;color:var(--muted);}\n.field{display:flex;flex-direction:column;gap:6px;margin:14px 0;}\n.field label{font-size:.88rem;font-weight:600;}\n.field input{padding:10px 12px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;}\n.field input.code{text-transform:uppercase;letter-spacing:.3em;font-weight:700;font-size:1.2rem;max-width:180px;}\n.topic-pick{display:grid;grid-template-columns:1fr 1fr;gap:8px;}\n.topic-pick button{padding:10px;border:1.5px solid var(--line);border-radius:8px;background:var(--card);cursor:pointer;font-weight:500;text-align:left;font-size:.92rem;}\n.topic-pick button:hover{border-color:var(--hema);}\n.rooms{margin-top:10px;display:flex;flex-direction:column;gap:8px;}\n.roomrow{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:var(--bg);font-size:.9rem;}\n.roomrow b{letter-spacing:.15em;color:var(--hema);}\n.sep{height:1px;background:var(--line);margin:18px 0;}\n.gbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px;}\n.gcode{font-weight:700;letter-spacing:.2em;color:var(--hema);background:var(--hema-soft);padding:4px 10px;border-radius:6px;}\n.people{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px;}\n.person{display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:var(--card);border:1px solid var(--line);font-size:.82rem;}\n.person.done{border-color:var(--ok);color:var(--ok);}\n.person .dot{width:7px;height:7px;border-radius:50%;background:var(--line);}\n.person.done .dot{background:var(--ok);}\n.person.lead{font-weight:700;}\n.opt.picked{border-color:var(--hema);background:var(--hema-soft);}\n.opt.picked .l{background:var(--hema);color:var(--card);}\n.chose{display:block;margin-top:6px;font-size:.8rem;font-weight:600;color:var(--hema);}\n.gstatus{margin-top:14px;font-size:.92rem;color:var(--muted);text-align:center;}\n.hostbar{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px;}\n.hostbar .primary{flex:1;margin:0;}\n.hostbar .ghost{flex-shrink:0;}\n.warn{padding:12px 14px;border-radius:8px;background:var(--eosin-soft);font-size:.92rem;}\n\n/* ---------- Robbins ---------- */\n.ref{display:flex;gap:10px;align-items:flex-start;margin-top:10px;padding:10px 12px;border-radius:8px;border:1px solid var(--line);font-size:.88rem;color:var(--muted);}\n.ref b{color:var(--hema);font-weight:600;}\n.book{position:relative;flex-shrink:0;width:15px;height:19px;margin-top:2px;border:2px solid var(--hema);border-radius:2px 4px 4px 2px;}\n.book::before{content:\"\";position:absolute;left:2px;top:-2px;bottom:-2px;width:2px;background:var(--hema);}\n.rmap{margin:0 0 26px;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 16px;}\n.rmap summary{cursor:pointer;font-weight:600;color:var(--hema);}\n.rmap h3{font-size:.98rem;margin:16px 0 6px;color:var(--ink);}\n.rmap ul{list-style:none;margin:0;padding:0;}\n.rmap li{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--line);font-size:.92rem;}\n.rmap li b{font-weight:600;color:var(--eosin);white-space:nowrap;font-size:.85rem;}\n.rmap li em{font-style:normal;color:var(--muted);font-size:.8rem;margin-left:4px;white-space:nowrap;}\n.refnote{margin-top:6px;font-size:.84rem;color:var(--bad);}\n.rmap .note{margin:12px 0 2px;font-size:.8rem;color:var(--muted);}\n\n/* ---------- Barra de progresso ---------- */\n.prog{grid-column:1/-1;padding:12px 16px 14px;border-top:1px solid var(--line);background:var(--card);}\n.prog-head{display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;margin-bottom:7px;}\n.prog-head b{font-family:var(--serif);font-size:1.3rem;color:var(--hema);font-variant-numeric:tabular-nums;}\n.prog-head .lbl{font-size:.88rem;font-weight:600;color:var(--ink);}\n.prog-head .det{margin-left:auto;font-size:.8rem;color:var(--muted);}\n.track{position:relative;height:12px;border-radius:12px;background:var(--frost2);overflow:hidden;}\n.track::after{content:\"\";position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,transparent calc(25% - 1px),var(--card) calc(25% - 1px) 25%,transparent 25% calc(50% - 1px),var(--card) calc(50% - 1px) 50%,transparent 50% calc(75% - 1px),var(--card) calc(75% - 1px) 75%,transparent 75%);opacity:.75;}\n.fill{display:block;height:100%;width:0;border-radius:12px;background:linear-gradient(90deg,var(--hema),var(--eosin));transition:width 1.1s cubic-bezier(.2,.8,.2,1);}\n.prog.full .fill{background:linear-gradient(90deg,var(--ok),var(--hema),var(--eosin));box-shadow:0 0 12px var(--eosin);}\n.prog.full .prog-head b{color:var(--ok);}\n.done .prog{border:1px solid var(--line);border-radius:10px;margin:18px 0 4px;text-align:left;}\n.gain{font-size:.85rem;font-weight:600;color:var(--ok);}\n@media (prefers-reduced-motion:reduce){.fill{transition:none}}\n\n/* ---------- Comemoração ---------- */\n.cheer{display:flex;align-items:center;gap:12px;margin:0 0 12px;padding:12px 14px;border-radius:10px;background:linear-gradient(100deg,var(--eosin-soft),var(--hema-soft));animation:pop .5s cubic-bezier(.2,1.5,.4,1) both;}\n.cheer .big{font-family:var(--serif);font-size:1.15rem;font-weight:700;color:var(--hema);line-height:1.25;}\n.cheer .sub{font-size:.88rem;color:var(--muted);}\n.cheer .dots{display:flex;gap:4px;flex-shrink:0;}\n.cheer .dots i{width:11px;height:11px;border-radius:50%;background:var(--eosin);box-shadow:inset -2px -2px 0 rgba(0,0,0,.12);animation:pop .4s cubic-bezier(.2,1.6,.4,1) both;}\n.cheer.lvl3{box-shadow:0 0 0 2px var(--eosin) inset;}\n.cheer.lvl4 .big{font-size:1.3rem;}\n@keyframes pop{0%{transform:scale(.6);opacity:0}100%{transform:scale(1);opacity:1}}\n.burst{position:fixed;inset:0;pointer-events:none;overflow:hidden;z-index:50;}\n.bit{position:absolute;left:var(--x);top:var(--y);width:var(--s);height:var(--s);margin:calc(var(--s) / -2) 0 0 calc(var(--s) / -2);border-radius:50%;background:var(--c);animation:fly var(--t) cubic-bezier(.15,.7,.3,1) forwards;}\n.bit.cell::after{content:\"\";position:absolute;inset:32%;border-radius:50%;background:var(--hema);opacity:.9;}\n@keyframes fly{\n  0%{transform:translate(0,0) scale(.2);opacity:1}\n  65%{opacity:1}\n  100%{transform:translate(var(--dx),var(--dy)) scale(1) rotate(var(--r));opacity:0}\n}\n@media (prefers-reduced-motion:reduce){.burst{display:none}.cheer,.cheer .dots i{animation:none}}\n\n/* ---------- Escolher quando volta ---------- */\n.custom{margin-top:14px;border:1.5px dashed var(--line);border-radius:8px;padding:10px 12px;}\n.custom summary{cursor:pointer;font-weight:600;color:var(--hema);font-size:.93rem;}\n.custom[open] summary{margin-bottom:10px;}\n.chips{display:flex;flex-wrap:wrap;gap:8px;}\n.chip{border:1.5px solid var(--line);background:var(--card);border-radius:999px;padding:7px 13px;cursor:pointer;font-size:.9rem;font-weight:500;}\n.chip:hover{border-color:var(--hema);}\n.own{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:10px;font-size:.9rem;color:var(--muted);}\n.own input{width:80px;padding:7px 10px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;}\n.own .err{color:var(--bad);width:100%;}\n\n/* ---------- Backup ---------- */\n.backup-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px;}\n.backup-row .ghost{flex:1;min-width:180px;}\n.panel{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:22px 20px;}\n.panel h2{font-size:1.4rem;color:var(--hema);margin-bottom:8px;}\n.panel p{color:var(--muted);margin:6px 0 14px;}\n.panel textarea{display:block;width:100%;min-height:130px;font-family:ui-monospace,\"SF Mono\",Menlo,Consolas,monospace;font-size:.78rem;line-height:1.4;padding:10px;border:1.5px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);resize:vertical;word-break:break-all;}\n.panel .row{justify-content:flex-start;}\n.msg{margin-top:12px;padding:10px 12px;border-radius:8px;font-size:.93rem;}\n.msg.ok{background:var(--ok-soft);color:var(--ok);}\n.msg.bad{background:var(--bad-soft);color:var(--bad);}\n\n@media (max-width:520px){\n  .slide{grid-template-columns:1fr;}\n  .slide .label{border-right:0;border-bottom:1px solid var(--line);}\n  .slide .glass{min-height:110px;}\n  .tissue{width:120px;}\n  .qcard{padding:18px 14px;}\n  .qtext{font-size:1.08rem;}\n}\n@media (prefers-reduced-motion:reduce){*{transition:none!important;}}\n</style>\n</head>\n<body>\n<div class=\"wrap\" id=\"app\"></div>\n\n<script>\n/* =========================================================\n   BANCO DE QUESTÕES\n   [id, assunto, origem, enunciado, alternativas, índice correto, comentário]\n   ========================================================= */\nconst TOPICS = {\n  adapt:   { name: \"Adaptações e lesão celular\", tissue: 0 },\n  aguda:   { name: \"Inflamação aguda\", tissue: 1 },\n  cronica: { name: \"Inflamação crônica e granulomatosa\", tissue: 2 }\n};\n\nconst A = \"Revisão N1, questão \";\nconst B = \"Revisão N1 (parte 2), questão \";\nconst C = \"Lista de adaptação e inflamação, pergunta \";\n\nconst QUESTIONS = [\n/* ---------- REVISÃO N1 (10 questões) ---------- */\n[\"a01\",\"adapt\",A+\"1\",\"Um homem de 65 anos com hipertensão arterial crônica apresenta aumento da massa muscular do ventrículo esquerdo. Qual processo adaptativo melhor descreve essa alteração?\",\n[\"Hiperplasia\",\"Hipertrofia\",\"Atrofia\",\"Metaplasia\"],1,\n\"Cardiomiócitos praticamente não se dividem. Diante da sobrecarga de pressão, cada célula sintetiza mais proteínas contráteis e aumenta de tamanho: hipertrofia. O órgão cresce porque as células cresceram, não porque aumentaram em número.\"],\n[\"a02\",\"adapt\",A+\"2\",\"A substituição do epitélio colunar ciliado do trato respiratório por epitélio escamoso estratificado em fumantes é um exemplo de:\",\n[\"Displasia\",\"Hiperplasia\",\"Atrofia\",\"Metaplasia\"],3,\n\"Metaplasia é a troca de um tipo celular adulto por outro tipo adulto, mais resistente à agressão (aqui, a fumaça). Displasia é outra coisa: desorganização com atipia celular, já no caminho para neoplasia.\"],\n[\"a03\",\"aguda\",A+\"3\",\"Qual é a sequência correta de eventos celulares na inflamação aguda?\",\n[\"Marginação, Rolamento, Adesão, Transmigração\",\"Quimiotaxia, Rolamento, Fagocitose, Adesão\",\"Vasodilatação, Estase, Edema, Apoptose\",\"Transmigração, Adesão, Rolamento, Marginação\"],0,\n\"Com a estase, os leucócitos vão para a periferia do vaso (marginação), rolam sobre o endotélio (selectinas), aderem firmemente (integrinas) e atravessam a parede (transmigração/diapedese, PECAM-1). A quimiotaxia acontece depois, já no tecido.\"],\n[\"a04\",\"aguda\",A+\"4\",\"Qual mediador químico é o principal responsável pela vasodilatação imediata e pelo aumento da permeabilidade vascular na inflamação aguda?\",\n[\"Interferon-gama\",\"Histamina\",\"Leucotrieno B4\",\"Fator de Necrose Tumoral (TNF)\"],1,\n\"A histamina já está pronta nos grânulos dos mastócitos e é liberada em segundos: dilata arteríolas e aumenta a permeabilidade das vênulas (fase imediata). TNF e IFN-γ são citocinas de ação mais tardia; o LTB4 é principalmente quimiotático para neutrófilos.\"],\n[\"a05\",\"cronica\",A+\"5\",\"A formação de granulomas, caracterizada por agregados de macrófagos epitelioides, é uma marca registrada de qual processo?\",\n[\"Adaptação Celular por Atrofia\",\"Inflamação Aguda Supurativa\",\"Inflamação Crônica\",\"Regeneração Tecidual\"],2,\n\"O granuloma é um padrão especial de inflamação crônica: agregados de macrófagos ativados (células epitelioides), muitas vezes com células gigantes e um halo de linfócitos.\"],\n[\"a06\",\"aguda\",A+\"6\",\"Durante a inflamação aguda, o aumento da permeabilidade vascular que permite a saída de fluido rico em proteínas e células para o interstício é chamado de:\",\n[\"Transudato\",\"Linfedema\",\"Edema hidrostático\",\"Exsudato\"],3,\n\"Exsudato: rico em proteínas e células, sai porque a permeabilidade vascular aumentou (é inflamatório). Transudato: pobre em proteínas, sai de vasos íntegros por aumento da pressão hidrostática ou queda da pressão oncótica.\"],\n[\"a07\",\"cronica\",A+\"7\",\"Qual citocina é considerada o “ativador mestre” dos macrófagos na inflamação crônica, sendo produzida principalmente por células T?\",\n[\"IL-4\",\"IL-8\",\"Interferon-gama (IFN-γ)\",\"IL-10\"],2,\n\"IFN-γ, produzido por linfócitos Th1 e células NK, é o grande ativador clássico (M1) dos macrófagos. IL-4 leva à ativação alternativa (M2), IL-10 é anti-inflamatória e IL-8 é quimiocina de neutrófilos.\"],\n[\"a08\",\"aguda\",A+\"8\",\"As selectinas são moléculas de adesão fundamentais para qual etapa do recrutamento leucocitário?\",\n[\"Adesão firme\",\"Rolamento\",\"Diapedese\",\"Fagocitose\"],1,\n\"Selectinas (E, P e L) fazem ligações de baixa afinidade que se formam e se desfazem o tempo todo, então o leucócito rola. A adesão firme é feita pelas integrinas ligando ICAM-1 e VCAM-1.\"],\n[\"a09\",\"adapt\",A+\"9\",\"Qual das seguintes alterações celulares é considerada uma resposta adaptativa à redução de nutrientes ou estimulação hormonal?\",\n[\"Metaplasia\",\"Hiperplasia\",\"Atrofia\",\"Necrose\"],2,\n\"Atrofia é a redução do tamanho celular por nutrição inadequada, menor aporte sanguíneo, desuso, perda de inervação ou perda de estímulo hormonal (ex.: endométrio após a menopausa). Atenção ao enunciado: o sentido é a perda da estimulação hormonal. Estimulação hormonal aumentada causaria hiperplasia.\"],\n[\"a10\",\"aguda\",A+\"10\",\"O sistema do complemento pode ser ativado por três vias. Qual componente é comum a todas as vias e leva à formação do complexo de ataque à membrana (MAC)?\",\n[\"Lectina de ligação à manose\",\"C1q\",\"C3\",\"Fator B\"],2,\n\"As vias clássica, alternativa e das lectinas convergem na clivagem de C3 pela C3 convertase. A partir daí: C3b, C5 convertase e C5b-9 (MAC). C1q é só da clássica, a lectina de ligação à manose só da via das lectinas e o fator B só da alternativa.\"],\n\n/* ---------- REVISÃO N1, PARTE 2 (50 questões) ---------- */\n[\"b01\",\"adapt\",B+\"1\",\"Qual mecanismo celular explica o aumento do útero durante a gravidez?\",\n[\"Apenas hipertrofia das fibras musculares.\",\"Apenas hiperplasia do endométrio.\",\"Combinação de hipertrofia e hiperplasia do miométrio.\",\"Metaplasia hormonal do colo uterino.\"],2,\n\"O estrogênio estimula as células musculares lisas do miométrio a aumentarem de tamanho (hipertrofia) e de número (hiperplasia). É o exemplo clássico das duas adaptações fisiológicas acontecendo juntas.\"],\n[\"b02\",\"adapt\",B+\"2\",\"A atrofia celular por desuso resulta principalmente de:\",\n[\"Aumento da síntese proteica.\",\"Redução da autofagia.\",\"Degradação de proteínas via ubiquitina-proteassoma.\",\"Substituição por tecido adiposo via metaplasia.\"],2,\n\"Na atrofia a célula sintetiza menos e degrada mais proteínas. A principal via de degradação é a ubiquitina-proteassoma: proteínas marcadas com ubiquitina são destruídas no proteassoma. A autofagia também aumenta, não diminui.\"],\n[\"b03\",\"adapt\",B+\"3\",\"Qual das seguintes opções descreve a patogênese da metaplasia?\",\n[\"Mudança no fenótipo de células já diferenciadas.\",\"Reprogramação de células-tronco teciduais.\",\"Divisão celular descontrolada.\",\"Morte celular programada seguida de regeneração.\"],1,\n\"A célula madura não se transforma em outra. O que acontece é a reprogramação das células-tronco/de reserva do tecido, que passam a se diferenciar em outra linhagem por influência de citocinas, fatores de crescimento e da matriz.\"],\n[\"b04\",\"adapt\",B+\"4\",\"A hiperplasia patológica é clinicamente importante porque:\",\n[\"Sempre evolui para necrose.\",\"Constitui um solo fértil para o surgimento de câncer.\",\"É um processo irreversível.\",\"Causa diminuição da função orgânica.\"],1,\n\"A hiperplasia patológica (ex.: endometrial por excesso de estrogênio) ainda é controlada e regride se o estímulo cessar. Mas as divisões celulares repetidas aumentam a chance de mutações, então ela é terreno para câncer (ex.: carcinoma de endométrio).\"],\n[\"b05\",\"adapt\",B+\"5\",\"Qual organela sofre aumento proeminente na hipertrofia dos hepatócitos induzida por barbitúricos?\",\n[\"Mitocôndria.\",\"Retículo endoplasmático rugoso.\",\"Retículo endoplasmático liso.\",\"Lisossomos.\"],2,\n\"Barbitúricos são metabolizados pelo sistema citocromo P-450, que fica no retículo endoplasmático liso. O hepatócito expande o REL para destoxificar mais, e isso explica a tolerância ao fármaco.\"],\n[\"b06\",\"adapt\",B+\"6\",\"A deficiência de Vitamina A pode induzir qual tipo de adaptação no epitélio respiratório?\",\n[\"Atrofia.\",\"Hiperplasia glandular.\",\"Metaplasia escamosa.\",\"Displasia grave.\"],2,\n\"O ácido retinoico (vitamina A) é necessário para manter a diferenciação normal do epitélio respiratório. Sem ele, o epitélio sofre metaplasia escamosa.\"],\n[\"b07\",\"adapt\",B+\"7\",\"O coração de um paciente com caquexia por câncer apresenta-se reduzido e com pigmentação acastanhada. O pigmento é:\",\n[\"Hemossiderina.\",\"Lipofuscina.\",\"Melanina.\",\"Bilirrubina.\"],1,\n\"Lipofuscina é o pigmento de “desgaste”: resíduo da peroxidação lipídica de membranas digeridas por autofagia. Castanho-amarelado e perinuclear, dá o aspecto de atrofia parda do coração em idosos e caquéticos.\"],\n[\"b08\",\"adapt\",B+\"8\",\"Qual o estímulo principal para a hiperplasia compensatória do fígado após hepatectomia parcial?\",\n[\"Hormônios esteroides.\",\"Citocinas e fatores de crescimento (HGF, IL-6).\",\"Isquemia relativa.\",\"Deposição de colágeno.\"],1,\n\"Os hepatócitos remanescentes saem de G0 e proliferam estimulados por fatores de crescimento (HGF, TGF-α) e citocinas (IL-6, TNF). É hiperplasia compensatória.\"],\n[\"b09\",\"adapt\",B+\"9\",\"Na adaptação celular, a autofagia é um processo de:\",\n[\"Ingestão de partículas externas.\",\"Digestão de componentes próprios da célula por lisossomos.\",\"Expulsão de organelas danificadas para o exsudato.\",\"Morte celular por inflamação.\"],1,\n\"Autofagia: a célula envolve seus próprios componentes em vacúolos autofágicos, que se fundem com lisossomos e são digeridos. Aumenta na atrofia e na privação de nutrientes. Ingerir partículas externas é fagocitose.\"],\n[\"b10\",\"adapt\",B+\"10\",\"A hipertrofia fisiológica do músculo esquelético de um atleta é estimulada principalmente via:\",\n[\"Via PI3K/AKT.\",\"Via G-proteína acoplada.\",\"Via da Caspase 3.\",\"Via do NF-kB.\"],0,\n\"Hipertrofia fisiológica (exercício, IGF-1) usa principalmente a via PI3K/AKT. A hipertrofia patológica (sobrecarga, angiotensina, endotelina) depende mais de receptores acoplados à proteína G. Caspase 3 é da apoptose.\"],\n[\"b11\",\"aguda\",B+\"11\",\"Qual evento vascular ocorre primeiro na inflamação aguda após uma lesão leve?\",\n[\"Vasoconstrição transitória das arteríolas.\",\"Vasodilatação capilar permanente.\",\"Aumento da pressão osmótica plasmática.\",\"Formação de trombos plaquetários.\"],0,\n\"Logo após a lesão há uma vasoconstrição arteriolar transitória, de segundos. Depois vem a vasodilatação, responsável por calor e rubor.\"],\n[\"b12\",\"aguda\",B+\"12\",\"O mecanismo mais comum de extravasamento vascular na inflamação aguda é:\",\n[\"Lesão endotelial direta.\",\"Contração das células endoteliais (fendas interendoteliais).\",\"Transcitose aumentada.\",\"Angiogênese de vasos imaturos.\"],1,\n\"O mecanismo mais comum é a contração das células endoteliais das vênulas pós-capilares, abrindo fendas entre elas. É induzido por histamina, bradicinina e leucotrienos, e é rápido e reversível (15 a 30 minutos).\"],\n[\"b13\",\"aguda\",B+\"13\",\"Qual molécula de adesão é expressa no endotélio após ativação por TNF e IL-1 para promover a adesão firme?\",\n[\"L-selectina.\",\"ICAM-1.\",\"Glicoproteína de Lewis X.\",\"PECAM-1.\"],1,\n\"TNF e IL-1 induzem no endotélio ICAM-1 e VCAM-1, que se ligam às integrinas dos leucócitos (LFA-1, VLA-4) e garantem a adesão firme. L-selectina e Lewis X participam do rolamento; PECAM-1, da transmigração.\"],\n[\"b14\",\"aguda\",B+\"14\",\"A quimiotaxia leucocitária é direcionada por:\",\n[\"Gradiente de concentração de substâncias químicas (ex: C5a, LTB4).\",\"Aumento da pressão hidrostática.\",\"Diminuição do pH local.\",\"Estase sanguínea.\"],0,\n\"Quimiotaxia é o movimento orientado por um gradiente químico. Os quimiotáticos podem ser exógenos (produtos bacterianos) ou endógenos (C5a, LTB4, IL-8 e outras quimiocinas).\"],\n[\"b15\",\"aguda\",B+\"15\",\"O “burst” oxidativo (explosão respiratória) nos neutrófilos produz:\",\n[\"Óxido nítrico apenas.\",\"Espécies reativas de oxigênio (ERO), como o ânion superóxido.\",\"Histamina estocada.\",\"Proteína C reativa.\"],1,\n\"A NADPH oxidase (oxidase do fagócito) reduz O₂ a ânion superóxido, que depois vira H₂O₂: são as ERO usadas para matar micróbios. A deficiência dessa enzima causa a doença granulomatosa crônica.\"],\n[\"b16\",\"aguda\",B+\"16\",\"Qual das seguintes é uma característica morfológica da inflamação serosa?\",\n[\"Presença de grande quantidade de neutrófilos e pus.\",\"Extravasamento de fluido pobre em proteínas (efusão).\",\"Formação de cicatriz fibrótica precoce.\",\"Presença de necrose caseosa.\"],1,\n\"Inflamação serosa é o extravasamento de líquido fino (efusão) em cavidades ou bolhas, como na bolha de queimadura ou no derrame pleural. O Robbins descreve o líquido como pobre em células; a alternativa fala em proteínas, mas é a única compatível.\"],\n[\"b17\",\"aguda\",B+\"17\",\"O sistema das cininas resulta na formação de bradicinina, que causa:\",\n[\"Vasoconstrição e hipertensão local.\",\"Dor e aumento da permeabilidade vascular.\",\"Inibição da quimiotaxia.\",\"Degradação do colágeno.\"],1,\n\"A bradicinina (fator XII, calicreína, cininogênio) aumenta a permeabilidade vascular, dilata vasos e causa dor. É inativada rapidamente pela cininase, que é a própria ECA.\"],\n[\"b18\",\"aguda\",B+\"18\",\"As NETs (Armadilhas Extracelulares de Neutrófilos) são compostas por:\",\n[\"Apenas citocinas inflamatórias.\",\"Rede de cromatina nuclear com proteínas granulares.\",\"Complexos antígeno-anticorpo.\",\"Membranas mitocondriais rompidas.\"],1,\n\"O neutrófilo libera sua cromatina em forma de rede, com histonas e proteínas antimicrobianas dos grânulos, que prendem e matam microrganismos. O neutrófilo morre no processo.\"],\n[\"b19\",\"aguda\",B+\"19\",\"Qual proteína plasmática da fase aguda é usada clinicamente como marcador de inflamação?\",\n[\"Albumina.\",\"Proteína C reativa (PCR).\",\"Hemoglobina.\",\"Troponina.\"],1,\n\"A PCR é produzida pelo fígado sob estímulo de IL-6 (e também IL-1 e TNF) e sobe muito na inflamação. A albumina faz o contrário: cai (proteína de fase aguda negativa).\"],\n[\"b20\",\"aguda\",B+\"20\",\"A resolução da inflamação aguda envolve a troca de metabólitos do ácido araquidônico de pró-inflamatórios para:\",\n[\"Leucotrienos.\",\"Tromboxanos.\",\"Lipoxinas.\",\"Prostaglandina E2.\"],2,\n\"Na resolução, a produção de mediadores lipídicos muda de prostaglandinas e leucotrienos (pró-inflamatórios) para lipoxinas (e resolvinas), que inibem o recrutamento de neutrófilos.\"],\n[\"b21\",\"aguda\",B+\"21\",\"Qual célula é a primeira a chegar ao local da lesão na inflamação aguda (nas primeiras 6-24h)?\",\n[\"Macrófago.\",\"Linfócito.\",\"Neutrófilo.\",\"Plasmócito.\"],2,\n\"Neutrófilos predominam nas primeiras 6 a 24 horas: são mais numerosos no sangue, respondem rápido às quimiocinas e aderem bem. Entre 24 e 48 horas são substituídos por monócitos/macrófagos.\"],\n[\"b22\",\"aguda\",B+\"22\",\"O exsudato purulento (pus) consiste principalmente em:\",\n[\"Monócitos e fibrina.\",\"Neutrófilos, detritos celulares e microrganismos.\",\"Líquido aquoso com pouca proteína.\",\"Hemácias e plaquetas.\"],1,\n\"Pus é exsudato rico em neutrófilos vivos e mortos, restos de células necróticas, edema e os próprios microrganismos. Típico de bactérias piogênicas, como o estafilococo.\"],\n[\"b23\",\"aguda\",B+\"23\",\"O que define uma úlcera?\",\n[\"Uma coleção de pus em um espaço fechado.\",\"Um defeito local na superfície de um órgão ou tecido por descamação de tecido necrótico inflamatório.\",\"O excesso de fluido no espaço intersticial.\",\"A substituição de células parenquimatosas por colágeno.\"],1,\n\"Úlcera é uma escavação na superfície de um órgão ou tecido causada pela descamação de tecido necrótico e inflamado. Coleção de pus em espaço fechado é abscesso.\"],\n[\"b24\",\"aguda\",B+\"24\",\"Qual enzima é responsável pela digestão do microrganismo dentro do fagolisossomo na presença de cloreto?\",\n[\"Mieloperoxidase (MPO).\",\"Catalase.\",\"Elastase.\",\"Colagenase.\"],0,\n\"A mieloperoxidase, dos grânulos azurófilos, usa H₂O₂ e cloreto para formar ácido hipocloroso (HOCl). O sistema H₂O₂-MPO-halogênio é o mais potente sistema bactericida do neutrófilo.\"],\n[\"b25\",\"aguda\",B+\"25\",\"A febre durante a inflamação é mediada por citocinas que estimulam a síntese de prostaglandinas no:\",\n[\"Fígado.\",\"Hipotálamo.\",\"Medula óssea.\",\"Córtex adrenal.\"],1,\n\"IL-1 e TNF (pirógenos endógenos) aumentam a COX e a PGE₂ no hipotálamo, que eleva o ponto de ajuste da temperatura. É por isso que anti-inflamatórios (inibidores da COX) baixam a febre.\"],\n[\"b26\",\"cronica\",B+\"26\",\"A inflamação crônica é caracterizada por:\",\n[\"Predomínio de neutrófilos e edema intenso.\",\"Infiltração por células mononucleares, destruição tecidual e tentativa de cura.\",\"Apenas congestão vascular e calor.\",\"Resolução completa em 48 horas.\"],1,\n\"Os três pilares da inflamação crônica acontecem ao mesmo tempo: infiltrado mononuclear (macrófagos, linfócitos, plasmócitos), destruição tecidual e tentativa de reparo (angiogênese e fibrose).\"],\n[\"b27\",\"cronica\",B+\"27\",\"Os macrófagos M1 (via clássica) são ativados por:\",\n[\"IL-4 e IL-13.\",\"Endotoxinas bacterianas e IFN-gama.\",\"Glicocorticoides.\",\"Vitamina D.\"],1,\n\"Via clássica (M1): produtos microbianos como a endotoxina (via TLR) e IFN-γ de células T. O resultado é um macrófago microbicida e pró-inflamatório. IL-4 e IL-13 levam ao M2.\"],\n[\"b28\",\"cronica\",B+\"28\",\"Os macrófagos M2 (via alternativa) têm como função principal:\",\n[\"Matar bactérias e fungos.\",\"Reparo tecidual e efeitos anti-inflamatórios.\",\"Apresentação de antígenos para células B apenas.\",\"Produção de óxido nítrico em grandes quantidades.\"],1,\n\"Macrófagos M2 (ativados por IL-4 e IL-13) são reparadores e anti-inflamatórios: produzem TGF-β e fatores de crescimento, estimulam angiogênese e fibrose. Matar micróbios e produzir NO é papel do M1.\"],\n[\"b29\",\"cronica\",B+\"29\",\"Células gigantes multinucleadas (tipo Langhans) na inflamação granulomatosa derivam da fusão de:\",\n[\"Neutrófilos.\",\"Macrófagos/Células epitelioides.\",\"Linfócitos B.\",\"Fibroblastos.\"],1,\n\"Células gigantes surgem da fusão de macrófagos/células epitelioides. Tipo Langhans: núcleos na periferia, em ferradura. Tipo corpo estranho: núcleos espalhados pelo citoplasma.\"],\n[\"b30\",\"cronica\",B+\"30\",\"Um granuloma com necrose central de aspecto “semelhante a queijo” é típico de:\",\n[\"Sarcoidose.\",\"Tuberculose.\",\"Reação a corpo estranho (fio de sutura).\",\"Doença de Crohn.\"],1,\n\"Necrose caseosa (branco-amarelada, friável, lembra queijo) no centro do granuloma é típica da tuberculose. Sarcoidose e Crohn formam granulomas não caseosos.\"],\n[\"b31\",\"cronica\",B+\"31\",\"Qual subpopulação de linfócitos T auxilia na defesa contra bactérias extracelulares e recruta neutrófilos?\",\n[\"Th1.\",\"Th2.\",\"Th17.\",\"T reguladores.\"],2,\n\"Th17 produz IL-17, que recruta neutrófilos e monócitos: defesa contra bactérias extracelulares e fungos. Th1 (IFN-γ) ativa macrófagos; Th2 (IL-4, IL-5, IL-13) atua sobre eosinófilos e macrófagos M2.\"],\n[\"b32\",\"cronica\",B+\"32\",\"A fibrose, uma marca da inflamação crônica, é o resultado da deposição excessiva de:\",\n[\"Glicogênio.\",\"Colágeno e outros componentes da matriz extracelular.\",\"Proteínas de choque térmico.\",\"Amiloide.\"],1,\n\"Fibrose é a deposição excessiva de colágeno e matriz extracelular pelos fibroblastos, estimulados principalmente por TGF-β, substituindo o parênquima.\"],\n[\"b33\",\"cronica\",B+\"33\",\"O que caracteriza um “granuloma de corpo estranho”?\",\n[\"Presença obrigatória de necrose caseosa.\",\"Ausência de resposta imune mediada por células T específica ao agente.\",\"Formado apenas por linfócitos.\",\"Causado sempre por Mycobacterium tuberculosis.\"],1,\n\"O granuloma de corpo estranho se forma ao redor de material inerte grande demais para ser fagocitado (fio de sutura, talco), sem resposta T específica. Os granulomas imunológicos, ao contrário, dependem de ativação de células T.\"],\n[\"b34\",\"cronica\",B+\"34\",\"Na inflamação crônica, o acúmulo de linfócitos, plasmócitos e macrófagos pode formar estruturas semelhantes a linfonodos chamadas:\",\n[\"Granulomas piogênicos.\",\"Órgãos linfoides terciários.\",\"Abscessos frios.\",\"Focos de Ghon.\"],1,\n\"Na inflamação crônica prolongada, linfócitos, células apresentadoras e plasmócitos se organizam em folículos, às vezes com centros germinativos: órgãos linfoides terciários (ex.: sinóvia na artrite reumatoide, tireoidite de Hashimoto).\"],\n[\"b35\",\"cronica\",B+\"35\",\"Qual citocina produzida pelos macrófagos estimula a migração e proliferação de fibroblastos?\",\n[\"IL-12.\",\"PDGF (Fator de Crescimento Derivado de Plaquetas).\",\"Histamina.\",\"Heparina.\"],1,\n\"O PDGF, produzido por macrófagos, plaquetas e endotélio, estimula a migração e a proliferação de fibroblastos e músculo liso. Tecnicamente é um fator de crescimento, não uma citocina clássica. IL-12 induz resposta Th1.\"],\n[\"b36\",\"aguda\",B+\"36\",\"A opsonização facilita a fagocitose. As principais opsoninas são:\",\n[\"IgG e C3b.\",\"IgE e Histamina.\",\"Leucotrienos e Prostaglandinas.\",\"Fibrinogênio e Albumina.\"],0,\n\"Opsoninas revestem o micróbio e são reconhecidas por receptores do fagócito: a IgG pelo receptor Fc e o C3b pelo receptor de complemento. Lectinas plasmáticas também opsonizam.\"],\n[\"b37\",\"cronica\",B+\"37\",\"O infiltrado celular em uma reação de hipersensibilidade aguda (alérgica) ou infecção parasitária é rico em:\",\n[\"Monócitos.\",\"Eosinófilos.\",\"Neutrófilos.\",\"Basófilos apenas.\"],1,\n\"Eosinófilos predominam em reações mediadas por IgE (alergia) e em parasitoses, recrutados por eotaxina e IL-5. A proteína básica principal dos seus grânulos é tóxica para helmintos.\"],\n[\"b38\",\"aguda\",B+\"38\",\"Qual a função da proteína do complemento C5a?\",\n[\"Opsonização de bactérias.\",\"Lise direta da parede celular via MAC.\",\"Quimiotaxia de leucócitos e anafilatoxina.\",\"Inibição da inflamação.\"],2,\n\"C5a (junto com C3a) é anafilatoxina: faz os mastócitos liberarem histamina. O C5a também é um potente quimiotático para neutrófilos. Opsonização é papel do C3b; lise é do MAC (C5b-9).\"],\n[\"b39\",\"aguda\",B+\"39\",\"A via da ciclooxigenase (COX) produz:\",\n[\"Leucotrienos.\",\"Prostaglandinas e Tromboxanos.\",\"Lipoxinas.\",\"Espécies reativas de oxigênio.\"],1,\n\"A COX (1 e 2) transforma o ácido araquidônico em prostaglandinas (PGE₂, PGI₂, PGD₂) e tromboxano A₂. Leucotrienos e lipoxinas vêm das lipoxigenases.\"],\n[\"b40\",\"cronica\",B+\"40\",\"A inflamação crônica pode ser causada por:\",\n[\"Infecções persistentes (ex: sífilis).\",\"Exposição prolongada a agentes tóxicos (ex: sílica).\",\"Doenças autoimunes.\",\"Todas as alternativas anteriores.\"],3,\n\"As três são causas clássicas: infecções persistentes (TB, sífilis, fungos), doenças de hipersensibilidade e autoimunes, e exposição prolongada a agentes tóxicos exógenos (sílica) ou endógenos (lipídios na aterosclerose).\"],\n[\"b41\",\"aguda\",B+\"41\",\"Qual o destino mais provável da inflamação aguda se o agente for eliminado e o tecido puder se regenerar?\",\n[\"Fibrose.\",\"Progressão para inflamação crônica.\",\"Resolução.\",\"Formação de abscesso.\"],2,\n\"Agente eliminado, lesão pequena e tecido capaz de regenerar: resolução, com retorno à estrutura normal. Fibrose ocorre quando a destruição é extensa ou o tecido não regenera.\"],\n[\"b42\",\"cronica\",B+\"42\",\"O que é a angiogênese, comum no processo de cura e inflamação crônica?\",\n[\"Morte de vasos sanguíneos.\",\"Formação de novos vasos a partir de vasos preexistentes.\",\"Contração de arteríolas.\",\"Deposição de cálcio na parede vascular.\"],1,\n\"Angiogênese é a formação de novos vasos por brotamento a partir de vasos que já existem, estimulada principalmente pelo VEGF. É um dos componentes do tecido de granulação.\"],\n[\"b43\",\"aguda\",B+\"43\",\"Na via do óxido nítrico (NO) nos macrófagos, o NO reage com superóxido para formar o radical altamente citotóxico:\",\n[\"Peroxinitrito.\",\"Ácido hipocloroso.\",\"Peróxido de hidrogênio.\",\"Hidroxila.\"],0,\n\"NO (da iNOS dos macrófagos ativados) + superóxido = peroxinitrito (ONOO⁻), muito reativo e microbicida. Ácido hipocloroso vem do sistema da mieloperoxidase.\"],\n[\"b44\",\"aguda\",B+\"44\",\"A adesão firme de leucócitos ao endotélio depende da ativação das:\",\n[\"Selectinas por quimiocinas.\",\"Integrinas (mudança para estado de alta afinidade).\",\"Caderinas.\",\"Mucinas.\"],1,\n\"Quimiocinas no endotélio ativam o leucócito e mudam as integrinas (LFA-1, VLA-4) para o estado de alta afinidade. Elas se ligam a ICAM-1 e VCAM-1 e o leucócito para de rolar.\"],\n[\"b45\",\"aguda\",B+\"45\",\"A morfologia da inflamação fibrinosa (ex: pericardite fibrinosa) ocorre quando:\",\n[\"O dano vascular é grande o suficiente para permitir a saída de moléculas grandes como fibrinogênio.\",\"Há apenas infecção viral leve.\",\"Ocorre hiperplasia do mesotélio.\",\"Não há exsudato proteico.\"],0,\n\"Com lesão vascular mais intensa, moléculas grandes como o fibrinogênio saem do vaso e viram fibrina no espaço extravascular. É típico de revestimentos de cavidades: pericárdio, pleura, meninges.\"],\n[\"b46\",\"adapt\",B+\"46\",\"A “morte celular programada” que não induz inflamação é a:\",\n[\"Necrose.\",\"Apoptose.\",\"Gangrena.\",\"Infarto.\"],1,\n\"Na apoptose a membrana continua íntegra e os corpos apoptóticos são fagocitados rapidamente. Como o conteúdo celular não vaza, não há inflamação. Na necrose, o conteúdo extravasa e inflama.\"],\n[\"b47\",\"aguda\",B+\"47\",\"O aumento de leucócitos imaturos no sangue durante uma infecção (“desvio à esquerda”) ocorre devido à ação de:\",\n[\"IL-10.\",\"CSFs (Fatores estimuladores de colônias).\",\"Serotonina.\",\"Colesterol.\"],1,\n\"Na infecção, IL-1 e TNF estimulam a produção de fatores estimuladores de colônias (CSFs), que aceleram a liberação de neutrófilos da medula, incluindo formas imaturas (bastões): desvio à esquerda.\"],\n[\"b48\",\"cronica\",B+\"48\",\"Células epitelioides são:\",\n[\"Células epiteliais que migraram para o tecido conjuntivo.\",\"Macrófagos ativados com citoplasma expandido que lembram células epiteliais.\",\"Células-tronco da pele.\",\"Células endoteliais em regeneração.\"],1,\n\"Células epitelioides são macrófagos ativados (por IFN-γ), com citoplasma amplo, rosado e granular e limites pouco nítidos, o que lembra epitélio. São a base do granuloma.\"],\n[\"b49\",\"aguda\",B+\"49\",\"O fator de Hageman (Fator XII) ativa quais sistemas?\",\n[\"Sistemas de coagulação e cininas.\",\"Apenas o sistema complemento.\",\"Apenas a via da COX-2.\",\"Ciclo de Krebs.\"],0,\n\"O fator XII, ativado por contato com colágeno, membrana basal ou superfícies negativas, dispara a coagulação (via intrínseca) e o sistema das cininas (bradicinina). Também participa da fibrinólise e pode ativar complemento, mas nunca “apenas” ele.\"],\n[\"b50\",\"adapt\",B+\"50\",\"Qual das seguintes opções é um exemplo de metaplasia tecidual comum no esôfago devido ao refluxo gástrico (Esôfago de Barrett)?\",\n[\"Escamosa para colunar/glandular.\",\"Glandular para escamosa.\",\"Mesenquimal para óssea.\",\"Atrofia glandular.\"],0,\n\"No esôfago de Barrett o epitélio escamoso é substituído por epitélio colunar de tipo intestinal (com células caliciformes) por causa do refluxo ácido. É lesão pré-maligna para adenocarcinoma. É o caminho inverso da metaplasia do fumante.\"],\n\n/* ---------- LISTA DE ADAPTAÇÃO E INFLAMAÇÃO (19 questões; o arquivo não tem a 17) ---------- */\n[\"c01\",\"adapt\",C+\"1\",\"Um paciente submetido a uma nefrectomia unilateral para remoção de um tumor renal apresenta, após alguns meses, aumento significativo do tamanho do rim remanescente. Qual é o mecanismo celular primário responsável por essa alteração?\",\n[\"Proliferação celular acelerada induzida por fatores de crescimento.\",\"Transformação fenotípica de fibroblastos em células tubulares.\",\"Aumento no tamanho individual das células renais.\",\"Inibição da autofagia com acúmulo de organelas hiperfuncionais.\"],2,\n\"O rim remanescente sofre hipertrofia compensatória: as células (principalmente tubulares) aumentam de tamanho para dar conta da carga de trabalho. Há pouca proliferação; o mecanismo primário é o aumento do tamanho celular.\"],\n[\"c02\",\"adapt\",C+\"2\",\"O útero grávido sofre um aumento dramático de volume e peso durante a gestação, retornando ao tamanho quase normal após o parto. Quais processos celulares participam consecutivamente desse ciclo?\",\n[\"Metaplasia escamosa seguida de necrose isquêmica.\",\"Displasia tecidual seguida de regeneração\",\"Hipertrofia e hiperplasia seguidas de atrofia por apoptose.\",\"Apenas hipertrofia isolada sem alteração no número celular.\"],2,\n\"Na gestação, o estrogênio causa hipertrofia e hiperplasia do miométrio. Depois do parto, com a queda hormonal, o útero involui: atrofia, com apoptose de células musculares.\"],\n[\"c03\",\"adapt\",C+\"3\",\"O epitélio respiratório de fumantes crônicos sofre frequentemente uma substituição do epitélio colunar pseudo-estratificado ciliado por epitélio pavimentoso estratificado. Qual é a principal implicação patológica dessa alteração?\",\n[\"Evolução direta e obrigatória para carcinoma adenocarcinoma invasivo.\",\"Aumento irreversível na secreção de surfactante pulmonar.\",\"Perda de mecanismos protetores mucociliares importantes.\",\"Transformação neoplásica benigna imediata do tecido conjuntivo.\"],2,\n\"O epitélio escamoso resiste melhor à fumaça, mas não tem cílios nem células caliciformes: perde-se a produção de muco e a depuração mucociliar. A metaplasia pode favorecer carcinoma (escamoso, não adenocarcinoma), mas não é obrigatória.\"],\n[\"c04\",\"aguda\",C+\"4\",\"Qual dos seguintes eventos vasculares iniciais ocorre classicamente logo após uma lesão tecidual aguda que desencadeia a inflamação?\",\n[\"Vasoconstrição transitória das arteríolas locais.\",\"Constrição permanente das vênulas pós-capilares.\",\"Vasodilatação prolongada mediada por fibronectina.\",\"Formação imediata de trombos oclusivos em capilares profundos.\"],0,\n\"Primeiro, vasoconstrição arteriolar transitória (segundos). Em seguida, vasodilatação mediada principalmente por histamina e NO, que causa calor e rubor.\"],\n[\"c05\",\"aguda\",C+\"5\",\"Qual o principal tipo celular encontrado no infiltrado inflamatório agudo nas primeiras 24 a 48 horas após uma infecção bacteriana piogênica?\",\n[\"Linfócitos T citotóxicos.\",\"Fibroblastos ativados.\",\"Neutrófilos polimorfonucleares.\",\"Eosinófilos hipersegmentados.\"],2,\n\"Bactérias piogênicas atraem neutrófilos polimorfonucleares, que dominam o infiltrado agudo inicial e formam o pus.\"],\n[\"c06\",\"aguda\",C+\"6\",\"Um abscesso cutâneo fechado caracterizado por acúmulo local de pus representa qual padrão morfológico de inflamação aguda?\",\n[\"Inflamação fibrinosa com deposição de malhas de fibrina densa.\",\"Inflamação supurativa (ou purulenta).\",\"Inflamação serosa com predomínio de transudato albumínico.\",\"Úlcera péptica de mucosa.\"],1,\n\"Abscesso é uma coleção localizada de pus (neutrófilos e necrose liquefativa) em espaço fechado: padrão supurativo ou purulento.\"],\n[\"c07\",\"aguda\",C+\"7\",\"A inflamação fibrinosa ocorre tipicamente em cavidades de revestimento corporal (como meninges, pericárdio e pleura). Qual é o destino final mais comum da fibrina acumulada se o estímulo inflamatório for leve a moderado?\",\n[\"Transformação metaplásica em cartilagem hialina.\",\"Conversão espontânea em cristais de colesterol.\",\"Remoção por fibrinólise e fagocitose por macrófagos (resolução).\",\"Calcificação distrófica maciça imediata sem fibrose.\"],2,\n\"A fibrina pode ser dissolvida por fibrinólise e removida por macrófagos: resolução. Se não for removida, é invadida por fibroblastos e vasos (organização) e vira tecido fibroso, com aderências.\"],\n[\"c08\",\"aguda\",C+\"8\",\"O que caracteriza morfologicamente uma úlcera em mucosas ou pele afetada por processo inflamatório agudo?\",\n[\"Proliferação benigna hiperplásica de glândulas mucosas com fibrose estromal.\",\"Defeito ou escavação local na superfície do órgão devido à esfoliação de tecido necrótico inflamado.\",\"Formação de uma falsa membrana pseudomembranosa na superfície luminal.\",\"Acúmulo encapsulado de tecido granulomatoso epiteloide estéril.\"],1,\n\"Úlcera é o defeito local na superfície causado pela descamação de tecido necrótico e inflamado. Pseudomembrana é outra coisa (exsudato fibrinoso aderido à superfície).\"],\n[\"c09\",\"aguda\",C+\"9\",\"Qual dos seguintes desfechos da inflamação aguda é caracterizado por completa restauração do tecido ao seu estado normal prévio, com remoção total do exsudato e debris?\",\n[\"Resolução.\",\"Organização (cicatrização por fibrose).\",\"Metaplasia regenerativa persistente.\",\"Progressão para inflamação crônica fibrinoide.\"],0,\n\"Resolução: o exsudato e os restos são removidos (drenagem linfática e macrófagos), os mediadores são neutralizados e o tecido volta ao normal. Organização é substituição por tecido fibroso.\"],\n[\"c10\",\"cronica\",C+\"10\",\"Diferente da inflamação aguda, a inflamação crônica é caracterizada histologicamente pela presença de quais tipos celulares principais?\",\n[\"Linfócitos, plasmócitos e macrófagos.\",\"Eosinófilos e mastócitos exclusivamente.\",\"Fibroblastos imaturos e osteoclastos gigantes.\",\"Neutrófilos polimorfonucleares e plaquetas ativadas.\"],0,\n\"Células mononucleares são a marca histológica da inflamação crônica: macrófagos (célula dominante), linfócitos e plasmócitos. Neutrófilos são a marca da aguda.\"],\n[\"c11\",\"cronica\",C+\"11\",\"O que caracteriza morfologicamente a inflamação granulomatosa, um subtipo especializado de inflamação crônica?\",\n[\"Presença de focos de necrose fibrinoide isolada sem células inflamatórias.\",\"Agregados compactos de macrófagos ativados modificados (células epitelióides), frequentemente cercados por linfócitos e células gigantes.\",\"Proliferação difusa de neutrófilos em meio a exsudato purulento extenso.\",\"Acúmulo exclusivo de mastócitos e eosinófilos em torno de vasos sanguíneos.\"],1,\n\"Granuloma: agregado compacto de células epitelioides (macrófagos ativados), frequentemente com células gigantes multinucleadas e um halo de linfócitos. Pode ou não ter necrose central.\"],\n[\"c12\",\"cronica\",C+\"12\",\"Na inflamação granulomatosa causada pelo agente da tuberculose (Mycobacterium tuberculosis), qual tipo de necrose é classicamente associado ao centro do granuloma?\",\n[\"Necrose caseosa.\",\"Necrose gangrenosa seca.\",\"Necrose gordurosa enzimática.\",\"Necrose liquefativa pura.\"],0,\n\"Na tuberculose o centro do granuloma tem necrose caseosa: material amorfo, granular, eosinofílico, sem contornos celulares, com aspecto macroscópico de queijo.\"],\n[\"c13\",\"cronica\",C+\"13\",\"Qual é a diferença fundamental entre granulomas imunológicos e granulomas de corpo estranho?\",\n[\"Granulomas de corpo estranho apresentam sempre necrose caseosa extensa.\",\"Não há distinção histológica ou etiológica descrita no Robbins.\",\"Granulomas de corpo estranho formam-se ao redor de materiais inertes grandes; granulomas imunológicos são induzidos por agentes persistentes que estimulam a imunidade mediada por células T.\",\"Granulomas imunológicos não contêm células gigantes, apenas neutrófilos necróticos.\"],2,\n\"Corpo estranho: material inerte grande demais para fagocitar (sutura, talco), sem resposta T específica. Imunológico: agente persistente ou pouco degradável que ativa células T (Th1, IFN-γ), que ativam os macrófagos. Ex.: TB.\"],\n[\"c14\",\"aguda\",C+\"14\",\"Quais são os principais sinais cardinais clássicos da inflamação descritos desde a antiguidade por Celsus e Virchow?\",\n[\"Prurido, vesiculação, atrofia, esclerose e ulceração.\",\"Febre, calafrios, leucocitose, caquexia e necrose.\",\"Rubor, calor, tumor, dor e perda de função.\",\"Palidez, cianose, hipotensão, choque e acidose.\"],2,\n\"Celsus descreveu rubor, calor, tumor e dor. Virchow acrescentou o quinto sinal: perda de função (functio laesa).\"],\n[\"c15\",\"aguda\",C+\"15\",\"O que diferencia primariamente um exsudato inflamatório de um transudato não inflamatório?\",\n[\"Não há diferença físico-química mensurável entre ambos na prática médica.\",\"O exsudato apresenta alta concentração de proteínas e densidade específica elevada, decorrente do aumento da permeabilidade vascular.\",\"O transudato contém grande quantidade de neutrófilos íntegros e restos celulares.\",\"O exsudato é formado exclusivamente por diminuição da pressão oncótica plasmática.\"],1,\n\"Exsudato: proteínas altas, densidade acima de 1,020, células e restos celulares, por aumento de permeabilidade. Transudato: pobre em proteínas, densidade baixa, vasos íntegros, causado por pressão hidrostática alta ou oncótica baixa.\"],\n[\"c16\",\"adapt\",C+\"16\",\"Qual é a consequência celular imediata sobre o tecido quando o suprimento sanguíneo é interrompido de forma abrupta, levando à hipóxia severa?\",\n[\"Aumento imediato na proliferação de mitocôndrias e síntese de glicogênio.\",\"Redução drástica na síntese de ATP pela fosforilação oxidativa mitocondrial.\",\"Ativação estrita de vias de reparo tecidual mediadas por colágeno tipo I.\",\"Conversão irreversível e imediata de todas as células em tecido adiposo.\"],1,\n\"Sem oxigênio, a fosforilação oxidativa para e o ATP despenca. Em cascata: falha da bomba Na⁺/K⁺ (edema celular), glicólise anaeróbia (acidose, queda do glicogênio) e queda da síntese proteica.\"],\n[\"c18\",\"adapt\",C+\"18\",\"Qual é a diferença fundamental entre calcificação distrófica e calcificação metastática segundo o Robbins?\",\n[\"A calcificação distrófica ocorre em tecidos necrosados com calcemia normal; a calcificação metastática ocorre em tecidos normais associada à hipercalcemia.\",\"Não existe diferença clínica ou patológica entre ambas as formas de calcificação.\",\"A calcificação distrófica requer níveis sistêmicos elevados de paratormônio.\",\"A calcificação metastática acomete exclusivamente válvulas cardíacas necróticas.\"],0,\n\"Distrófica: em tecido morto ou lesado, com cálcio sérico normal (ateromas, valvas lesadas, necrose caseosa). Metastática: em tecido normal, por hipercalcemia (hiperparatireoidismo, destruição óssea, excesso de vitamina D).\"],\n[\"c19\",\"aguda\",C+\"19\",\"Qual é a principal função morfológica e patológica da inflamação fibrinosa que ocorre classicamente no pericárdio ou na pleura?\",\n[\"Formação imediata de necrose caseosa generalizada com cavitação pulmonar estéril.\",\"Proliferação neoplásica benigna de células mesoteliais induzida por infecção viral.\",\"Acúmulo de exsudato rico em fibrinogênio que se converte em fibrina, podendo sofrer resolução ou resultar em fibrose e aderências (organização).\",\"Acúmulo estrito de neutrófilos e liquefação necrótica purulenta em cavidade fechada.\"],2,\n\"O fibrinogênio extravasado vira fibrina. Dois destinos: fibrinólise e remoção (resolução) ou organização por fibroblastos e vasos, deixando fibrose e aderências (ex.: pericardite constritiva).\"],\n[\"c20\",\"cronica\",C+\"20\",\"Em uma úlcera péptica ou cutânea crônica, qual é a principal alteração histológica encontrada na base e nas bordas da lesão ao longo do tempo?\",\n[\"Metaplasia escamosa total do tecido muscular subjacente sem infiltrado inflamatório.\",\"Presença exclusiva de neutrófilos degenerados sem qualquer sinal de cicatrização ou tecido de granulação.\",\"Combinação de inflamação aguda na base, infiltrado mononuclear crônico periférico, proliferação de fibroblastos e angiogênese (tecido de granulação).\",\"Transformação sarcomatosa maligna imediata de células endoteliais locais.\"],2,\n\"Na úlcera crônica coexistem: inflamação aguda na base (neutrófilos), infiltrado mononuclear nas bordas e tentativa de reparo com tecido de granulação (fibroblastos e novos vasos), que evolui para cicatriz.\"]\n];\n\n/* =========================================================\n   POR QUE CADA ALTERNATIVA ESTÁ ERRADA + MACETE\n   EXTRA[id] = [[motivo por alternativa (null na correta)], \"macete\"]\n   ========================================================= */\nconst EXTRA = {\na01:[[\"Hiperplasia é aumento do NÚMERO de células. Cardiomiócitos adultos praticamente não se dividem, então não conseguem responder assim.\",null,\"Atrofia é o oposto: a célula diminui, por menos demanda ou menos estímulo.\",\"Metaplasia é a troca de um tipo celular por outro. O miocárdio continua sendo miocárdio.\"],\n\"Célula que não divide só pode crescer: coração e músculo esquelético respondem à sobrecarga com hipertrofia. Pense: “quem não multiplica, engorda”.\"],\na02:[[\"Displasia é crescimento desordenado com atipia (núcleos alterados, perda da organização). Aqui um epitélio normal só foi trocado por outro normal.\",\"Hiperplasia aumentaria o número das mesmas células colunares, sem mudar o tipo de epitélio.\",\"Atrofia reduziria o tamanho das células, sem trocar o tipo.\",null],\n\"METAplasia = METAmorfose do tecido: um epitélio adulto e normal vira outro, mais resistente. No fumante, o brônquio “veste uma armadura” de epitélio escamoso.\"],\na03:[[null,\"Mistura as etapas: a quimiotaxia acontece depois da transmigração, e a fagocitose é o fim do processo, não vem antes da adesão.\",\"Vasodilatação, estase e edema são eventos vasculares, não celulares. E apoptose não faz parte do recrutamento.\",\"São as etapas certas, mas na ordem de trás para frente.\"],\n\"Pense num carro entrando num estacionamento: encosta na lateral (marginação), anda devagar (rolamento), estaciona (adesão) e o motorista sai (transmigração). Sigla M-R-A-T.\"],\na04:[[\"IFN-γ é citocina de linfócitos T e NK que ativa macrófagos. Age em horas a dias, não em segundos.\",null,\"LTB4 é principalmente quimiotático para neutrófilos. Os leucotrienos que aumentam a permeabilidade são C4, D4 e E4.\",\"TNF precisa ser sintetizado, então age mais tarde, ativando endotélio e leucócitos.\"],\n\"Imediato = pré-formado. A histamina já está “engatilhada” nos grânulos do mastócito: basta degranular. A vermelhidão da picada de inseto em segundos é histamina.\"],\na05:[[\"Atrofia é adaptação celular (redução de tamanho), sem agregados de macrófagos.\",\"A supurativa é aguda, dominada por neutrófilos e pus, não por macrófagos epitelioides.\",null,\"Regeneração é reposição de células do mesmo tipo. Granuloma é inflamação, não reparo.\"],\n\"Granuloma é a “muralha” que o corpo constrói quando não consegue eliminar o agressor. Se precisou construir muralha, é porque a briga é longa: crônica.\"],\na06:[[\"Transudato é pobre em proteínas e células e sai de vasos íntegros por desequilíbrio de pressões.\",\"Linfedema é edema por obstrução da drenagem linfática, não por aumento da permeabilidade.\",\"Edema hidrostático vem do aumento de pressão (ex.: insuficiência cardíaca) com o vaso íntegro, e o líquido é transudato.\",null],\n\"EXsudato: EXtravasa tudo (proteína e célula) porque o vaso “furou”. TRANSudato: só o líquido atravessa um vaso íntegro.\"],\na07:[[\"IL-4 (com IL-13) faz a ativação alternativa (M2), voltada para reparo.\",\"IL-8 é quimiocina que atrai neutrófilos. Não ativa macrófagos.\",null,\"IL-10 é anti-inflamatória: desliga macrófagos.\"],\n\"IFN-Gama é o Gatilho do macrófago matador (M1). Macrófago ativado por IFN-γ vira a célula epitelioide do granuloma.\"],\na08:[[\"Adesão firme é função das integrinas (LFA-1, VLA-4) ligando ICAM-1 e VCAM-1.\",null,\"A diapedese (transmigração) depende principalmente da PECAM-1 (CD31).\",\"A fagocitose acontece no tecido, por receptores de opsoninas e de padrões microbianos.\"],\n\"Selectina “seleciona e solta”: liga fraco, pega e solta, pega e solta, e o leucócito rola. Integrina “integra” firme, e ele para.\"],\na09:[[\"Metaplasia é resposta a irritação crônica, trocando o tipo celular. Não é causada por falta de nutrientes.\",\"Hiperplasia responde a AUMENTO de estímulo (hormônios, fatores de crescimento).\",null,\"Necrose é morte celular, não adaptação.\"],\n\"Atrofia é “modo economia”: faltou comida, sangue, uso, nervo ou hormônio, a célula encolhe para sobreviver.\"],\na10:[[\"A lectina de ligação à manose inicia só a via das lectinas.\",\"C1q inicia só a via clássica, ligando anticorpos (IgG, IgM).\",null,\"O fator B participa só da via alternativa.\"],\n\"As três vias são estradas diferentes que chegam na mesma praça: C3. De lá saem C3b (opsoniza), C3a e C5a (inflamam) e o MAC (lisa).\"],\n\nb01:[[\"O “apenas” derruba: além de crescer, as células musculares lisas também se multiplicam.\",\"O aumento é do miométrio (músculo), não só do endométrio, e envolve também hipertrofia.\",null,\"Metaplasia não explica aumento de volume. O útero cresce por adaptação do músculo.\"],\n\"Músculo liso consegue dividir E crescer, então usa as duas armas. Em prova, desconfie de alternativas com “apenas”.\"],\nb02:[[\"Na atrofia a síntese de proteínas diminui.\",\"A autofagia aumenta na atrofia (a célula recicla partes de si).\",null,\"Substituição por gordura pode ocorrer no órgão, mas não é metaplasia nem o mecanismo celular da atrofia.\"],\n\"Ubiquitina é a “etiqueta de lixo”: a proteína marcada vai para o proteassoma, o “triturador”. Atrofia = menos fabricação + mais trituração.\"],\nb03:[[\"Célula já diferenciada não muda de tipo. Esse é o erro clássico que a questão quer pegar.\",null,\"Divisão descontrolada é característica de neoplasia. A metaplasia é reversível.\",\"Não há morte programada seguida de regeneração: a troca vem da diferenciação diferente das células-tronco.\"],\n\"Metaplasia não é a célula madura trocando de roupa. É a fábrica (célula-tronco) que muda o molde.\"],\nb04:[[\"Hiperplasia não evolui para necrose. São processos diferentes.\",null,\"Hiperplasia é reversível: tirou o estímulo, ela regride. Isso a diferencia da neoplasia.\",\"O tecido hiperplásico em geral mantém ou aumenta a função.\"],\n\"Hiperplasia patológica é “reversível, mas perigosa”: cada divisão a mais é uma chance de mutação. Ex.: hiperplasia endometrial → carcinoma de endométrio.\"],\nb05:[[\"Mitocôndrias não são o local de metabolização de barbitúricos.\",\"O RER sintetiza proteínas para exportação, não destoxifica fármacos.\",null,\"Lisossomos fazem digestão intracelular, não metabolizam fármacos.\"],\n\"REL = Retículo da Eliminação de drogas (citocromo P-450). Mais droga, mais REL, e mais tolerância ao remédio.\"],\nb06:[[\"A falta de vitamina A não apenas reduz as células: ela muda o tipo de epitélio.\",\"Não há aumento de glândulas. Ao contrário, perde-se o epitélio secretor.\",null,\"Displasia não é consequência direta da deficiência. A resposta é adaptativa (metaplasia).\"],\n\"Vitamina A mantém o epitélio “especializado” (secretor, ciliado). Sem ela, o epitélio “simplifica” para escamoso. No olho, isso causa a xeroftalmia.\"],\nb07:[[\"Hemossiderina vem do ferro (hemorragia, sobrecarga de ferro), não do desgaste celular.\",null,\"Melanina é pigmento de melanócitos, não de cardiomiócitos.\",\"Bilirrubina causa icterícia, não pigmento perinuclear em células atróficas.\"],\n\"Lipofuscina = pigmento “da idade”: Lipo (gordura oxidada) + fusc (escuro). Coração pequeno e marrom = atrofia parda.\"],\nb08:[[\"Esteroides não são o principal estímulo da regeneração hepática.\",null,\"Isquemia não estimula proliferação, ela causa lesão.\",\"Colágeno é produto da fibrose, não estímulo para hiperplasia.\"],\n\"HGF = Hepatocyte Growth Factor, o nome já entrega. A IL-6 “acorda” o hepatócito (tira de G0) e o HGF manda ele dividir.\"],\nb09:[[\"Ingerir material de fora é fagocitose (heterofagia).\",null,\"A célula não expulsa organelas para o exsudato. Ela as digere internamente.\",\"Autofagia é mecanismo de sobrevivência, não morte por inflamação.\"],\n\"AUTO-fagia = comer a si mesmo. Em jejum, a célula recicla peças velhas para sobreviver.\"],\nb10:[[null,\"Receptores acoplados à proteína G predominam na hipertrofia patológica (angiotensina, endotelina, catecolaminas).\",\"Caspase 3 é executora da apoptose, não de crescimento.\",\"NF-κB é fator de transcrição ligado principalmente à inflamação.\"],\n\"Atleta = “AKT-leta”: exercício → IGF-1 → PI3K/AKT (hipertrofia boa). Doença, como a hipertensão → proteína G (hipertrofia ruim).\"],\nb11:[[null,\"A vasodilatação vem depois, e não é permanente.\",\"Na inflamação o que sobe é a pressão osmótica do interstício, pela saída de proteínas. Não é o primeiro evento.\",\"Trombos não são o primeiro evento da inflamação aguda.\"],\n\"Primeiro o susto (contrai), depois a festa (dilata). A constrição dura só segundos.\"],\nb12:[[\"Lesão endotelial direta acontece em agressões graves (queimaduras, toxinas). Não é o mais comum.\",null,\"Transcitose aumentada existe (ex.: estímulo por VEGF), mas é mecanismo secundário.\",\"Vasos novos vazam, mas isso é típico do reparo, não do extravasamento agudo.\"],\n\"As células endoteliais “encolhem os ombros” (contraem) e abrem frestas. É rápido, dura 15 a 30 minutos e é típico da histamina.\"],\nb13:[[\"L-selectina fica no leucócito (L de leucócito) e participa do rolamento.\",null,\"Sialil-Lewis X é o ligante das selectinas no leucócito: também rolamento.\",\"PECAM-1 (CD31) atua na transmigração.\"],\n\"TNF e IL-1 “acendem” o endotélio, que passa a expor ICAM-1 e VCAM-1: são as mãos que seguram a integrina do leucócito.\"],\nb14:[[null,\"Pressão hidrostática move líquido, não orienta leucócitos.\",\"pH baixo não é o sinal que direciona a migração.\",\"A estase ajuda a marginação, mas não dá direção ao leucócito no tecido.\"],\n\"Quimio-taxia = movimento guiado pela química. O leucócito “segue o cheiro” do mais fraco para o mais forte: C5a, LTB4, IL-8 e produtos bacterianos.\"],\nb15:[[\"O NO vem da iNOS, principalmente em macrófagos. O burst oxidativo gera ERO.\",null,\"Histamina é de mastócitos, não produto do burst.\",\"A PCR é produzida pelo fígado.\"],\n\"Burst = explosão de oxigênio: a NADPH oxidase joga elétrons no O₂ e forma superóxido. Sem essa enzima: doença granulomatosa crônica (infecções de repetição).\"],\nb16:[[\"Neutrófilos e pus definem a inflamação supurativa (purulenta).\",null,\"A serosa é leve e costuma resolver, sem cicatriz.\",\"Necrose caseosa é da tuberculose (granulomatosa).\"],\n\"Serosa = “soro”: líquido claro e ralo. Bolha de queimadura é o exemplo clássico.\"],\nb17:[[\"A bradicinina é vasodilatadora: causa hipotensão, não hipertensão.\",null,\"Ela não inibe a quimiotaxia.\",\"Ela não é enzima de matriz.\"],\n\"BradiCINina = DOR. Na clínica: o IECA impede a quebra da bradicinina e por isso causa tosse e angioedema.\"],\nb18:[[\"NETs não são citocinas. São estruturas físicas feitas de DNA.\",null,\"Complexos antígeno-anticorpo são outra coisa (hipersensibilidade tipo III).\",\"Não são membranas mitocondriais.\"],\n\"NET = rede de pesca: fios de cromatina com “iscas” antimicrobianas dos grânulos. O neutrófilo morre ao lançar a rede.\"],\nb19:[[\"A albumina CAI na inflamação (proteína de fase aguda negativa).\",null,\"Hemoglobina não é proteína de fase aguda.\",\"Troponina é marcador de lesão do miocárdio.\"],\n\"Inflamou, a IL-6 manda o fígado fazer PCR. O fibrinogênio também sobe, e é por isso que o VHS aumenta.\"],\nb20:[[\"Leucotrienos são pró-inflamatórios.\",\"Tromboxano é pró-agregante e vasoconstritor.\",null,\"PGE2 é pró-inflamatória (dor, febre, vasodilatação).\"],\n\"LipOXINAS dão o “X” final na inflamação: mandam os neutrófilos pararem de chegar. Guarde: lipoxinas = resolução.\"],\nb21:[[\"Macrófagos predominam depois, a partir de 24 a 48 horas.\",\"Linfócitos marcam inflamação crônica ou viral.\",null,\"Plasmócitos são da inflamação crônica.\"],\n\"Neutrófilo é o bombeiro: primeiro a chegar e vive pouco. Macrófago é o faxineiro que chega depois e fica.\"],\nb22:[[\"Fibrina é da inflamação fibrinosa, e monócitos não são o principal componente do pus.\",null,\"Líquido aquoso pobre em proteína é o da inflamação serosa.\",\"Hemácias predominariam num exsudato hemorrágico.\"],\n\"Pus = neutrófilo + lixo + bactéria. Piogênico = “gera pus”, como o estafilococo.\"],\nb23:[[\"Coleção de pus em espaço fechado é abscesso.\",null,\"Excesso de fluido no interstício é edema.\",\"Substituição do parênquima por colágeno é fibrose.\"],\n\"Úlcera = buraco na superfície (pele, mucosa). Abscesso = bolsa de pus fechada.\"],\nb24:[[null,\"A catalase degrada H₂O₂, ou seja, faz o contrário.\",\"A elastase é protease que degrada proteínas e tecido, sem usar cloreto.\",\"A colagenase degrada colágeno da matriz.\"],\n\"MPO + Cl⁻ + H₂O₂ = HOCl, a “água sanitária” do neutrófilo.\"],\nb25:[[\"O fígado produz proteínas de fase aguda, mas não regula a temperatura.\",null,\"A medula produz leucócitos (leucocitose), não a febre.\",\"O córtex adrenal produz cortisol, que é anti-inflamatório.\"],\n\"Hipotálamo = termostato. A PGE₂ “sobe o termostato”. Por isso aspirina e dipirona baixam a febre.\"],\nb26:[[\"Neutrófilos e edema intenso descrevem a inflamação aguda.\",null,\"Congestão e calor são sinais vasculares da aguda.\",\"Resolução rápida é desfecho da aguda.\"],\n\"Crônica = três coisas ao mesmo tempo: mononucleares, destruição e reparo. “Briga, estraga e conserta junto”.\"],\nb27:[[\"IL-4 e IL-13 fazem a ativação alternativa (M2).\",null,\"Glicocorticoides inibem os macrófagos.\",\"Vitamina D não é o ativador clássico.\"],\n\"M1 = Mata (endotoxina + IFN-γ). M2 = Monta de novo, ou seja, repara (IL-4, IL-13).\"],\nb28:[[\"Matar microrganismos é função do M1.\",null,\"Apresentar antígenos não é “apenas para células B”, nem é a função principal do M2.\",\"NO em grande quantidade é produto do M1.\"],\n\"M1 = Mata. M2 = Monta de novo: reparo, fibrose, angiogênese e controle da inflamação.\"],\nb29:[[\"Neutrófilos não se fundem em células gigantes.\",null,\"Linfócitos B viram plasmócitos, não células gigantes.\",\"Fibroblastos produzem colágeno e não se fundem.\"],\n\"Célula gigante = vários macrófagos “dando as mãos” (fusão) para englobar algo grande. Langhans tem os núcleos em ferradura na borda.\"],\nb30:[[\"A sarcoidose tem granulomas NÃO caseosos.\",null,\"O granuloma de corpo estranho não tem necrose caseosa: tem o material estranho no centro.\",\"A doença de Crohn tem granulomas não caseosos.\"],\n\"Caseosa = queijo = tuberculose (também alguns fungos). “A tuberculose come queijo”.\"],\nb31:[[\"Th1 (IFN-γ) ativa macrófagos contra microrganismos intracelulares.\",\"Th2 (IL-4, IL-5, IL-13) atua contra helmintos e na alergia, recrutando eosinófilos.\",null,\"T reguladores suprimem a resposta imune.\"],\n\"Th1 → macrófago. Th2 → eosinófilo. Th17 → neutrófilo. “O 17 chama o exército de neutrófilos”.\"],\nb32:[[\"Acúmulo de glicogênio é depósito intracelular (ex.: glicogenoses).\",null,\"Proteínas de choque térmico são chaperonas dentro da célula.\",\"Amiloide é depósito de proteína mal dobrada (amiloidose), não fibrose.\"],\n\"Fibrose = cicatriz de colágeno. O maestro é o TGF-β, que manda o fibroblasto produzir matriz.\"],\nb33:[[\"O granuloma de corpo estranho não tem necrose caseosa.\",null,\"Ele é formado por macrófagos e células gigantes, não só por linfócitos.\",\"É causado por material inerte, não pela tuberculose.\"],\n\"Corpo estranho = macrófago sem imunologia: o corpo não “reconhece” o fio de sutura, só tenta englobá-lo.\"],\nb34:[[\"Granuloma piogênico é uma lesão vascular proliferativa. O nome engana: não é granuloma nem tem pus.\",null,\"Abscesso frio é uma coleção sem sinais inflamatórios agudos, típica da tuberculose.\",\"Foco de Ghon é a lesão da tuberculose primária no pulmão.\"],\n\"Terciário = terceiro tipo de órgão linfoide (depois dos primários e secundários): o tecido inflamado cria seu próprio “linfonodo”.\"],\nb35:[[\"IL-12 induz resposta Th1, não fibroblastos.\",null,\"Histamina é mediador vascular agudo.\",\"Heparina é anticoagulante liberado por mastócitos.\"],\n\"PDGF: “Puxa e Divide Fibroblastos”. Atrai e multiplica.\"],\nb36:[[null,\"IgE se liga a mastócitos (alergia). Histamina é mediador vascular.\",\"Leucotrienos e prostaglandinas são mediadores lipídicos, não opsoninas.\",\"Fibrinogênio e albumina não são as opsoninas principais.\"],\n\"Opsonina é o “tempero” que deixa o micróbio apetitoso para o fagócito. As principais: IgG e C3b.\"],\nb37:[[\"Monócitos predominam na crônica em geral, não na alergia e na parasitose.\",null,\"Neutrófilos predominam nas infecções bacterianas agudas.\",\"Basófilos participam, mas são poucos, e o “apenas” invalida.\"],\n\"Eosinófilo = alergia e verme. IgE e parasita no enunciado? Pense em eosinófilo.\"],\nb38:[[\"Opsonização é função do C3b.\",\"A lise é feita pelo MAC (C5b-C9).\",null,\"C5a é pró-inflamatório, não inibe a inflamação.\"],\n\"Fragmentos “a” (C3a, C5a) Alarmam: são anafilatoxinas. Fragmento C3b “Bota etiqueta” no micróbio (opsoniza).\"],\nb39:[[\"Leucotrienos vêm da 5-lipoxigenase.\",null,\"Lipoxinas também vêm das lipoxigenases.\",\"ERO vêm da NADPH oxidase.\"],\n\"COX → Prostaglandinas + Tromboxano (a aspirina bloqueia). LOX → Leucotrienos + Lipoxinas: “L com L”.\"],\nb40:[[\"Está correta, mas é só uma das causas.\",\"Está correta, mas é só uma das causas.\",\"Está correta, mas é só uma das causas.\",null],\n\"Causas de inflamação crônica: infecção que persiste, doença imune (autoimune ou alérgica) e agente tóxico prolongado (sílica, lipídios).\"],\nb41:[[\"Fibrose ocorre quando o dano é extenso ou o tecido não consegue regenerar.\",\"Progressão para crônica acontece quando o agente persiste.\",null,\"Abscesso ocorre com bactérias piogênicas não contidas.\"],\n\"Agente eliminado + tecido que regenera = tudo volta ao normal (resolução).\"],\nb42:[[\"É o oposto do que acontece.\",null,\"Contração de arteríolas é vasoconstrição.\",\"Deposição de cálcio na parede é calcificação vascular.\"],\n\"Angio-gênese = nascimento de vasos por brotamento. O motor principal é o VEGF.\"],\nb43:[[null,\"Ácido hipocloroso vem de MPO + H₂O₂ + Cl⁻.\",\"H₂O₂ vem da conversão do superóxido.\",\"A hidroxila vem do H₂O₂ com ferro (reação de Fenton).\"],\n\"NO + superóxido = peroxiNITRITO. Tem “nitro” no nome porque veio do óxido NÍTRICO.\"],\nb44:[[\"Selectinas fazem o rolamento. As quimiocinas ativam integrinas, não selectinas.\",null,\"Caderinas fazem junções entre células.\",\"Mucinas são glicoproteínas do muco.\"],\n\"A quimiocina “aperta o botão” da integrina: de baixa para alta afinidade, e o leucócito freia.\"],\nb45:[[null,\"Infecção viral leve tende a causar inflamação serosa.\",\"Hiperplasia do mesotélio não define o padrão fibrinoso.\",\"A inflamação fibrinosa exige exsudato rico em proteínas.\"],\n\"Fibrinogênio é molécula GRANDE: só sai se o vaso estiver bem lesado. Pericardite fibrinosa dá o atrito pericárdico na ausculta.\"],\nb46:[[\"Na necrose a membrana rompe, o conteúdo vaza e há inflamação.\",null,\"Gangrena é necrose de um membro ou tecido.\",\"Infarto é necrose isquêmica.\"],\n\"Apoptose é a morte “educada”: empacota tudo em corpos apoptóticos e não suja o chão. Necrose explode e inflama.\"],\nb47:[[\"IL-10 é anti-inflamatória.\",null,\"Serotonina é amina vasoativa, sem papel na medula.\",\"Colesterol não estimula a medula óssea.\"],\n\"CSF acelera a “fábrica” da medula, que manda até os “estagiários” (bastões) para o sangue: desvio à esquerda.\"],\nb48:[[\"Epitelioide não é epitélio. É macrófago parecido com epitélio.\",null,\"Não são células-tronco.\",\"Não são células endoteliais.\"],\n\"Epitelioide = “com cara de” epitélio (o sufixo -oide significa parecido). É um macrófago fantasiado.\"],\nb49:[[null,\"Pode ativar complemento, mas o “apenas” deixa errada.\",\"A COX-2 não é ativada pelo fator XII.\",\"Ciclo de Krebs é metabolismo energético.\"],\n\"Fator XII (Hageman) é o “faz-tudo” do plasma: coagulação, cininas (bradicinina) e fibrinólise.\"],\nb50:[[null,\"Colunar para escamoso é o que acontece no brônquio do fumante, o inverso.\",\"Metaplasia óssea ocorre em tecido conjuntivo, não no epitélio do esôfago.\",\"Atrofia não é metaplasia.\"],\n\"Barrett: o esôfago “vira intestino” para aguentar o ácido. Fumante: o brônquio “vira pele”. São caminhos opostos.\"],\n\nc01:[[\"No rim adulto o crescimento compensatório é principalmente por aumento das células, não por proliferação.\",\"Fibroblasto não se transforma em célula tubular.\",null,\"Não é por inibição de autofagia.\"],\n\"Perdeu um rim? O que sobrou “malha”: as células crescem (hipertrofia compensatória).\"],\nc02:[[\"Não há metaplasia nem necrose no ciclo da gestação.\",\"Displasia é alteração pré-neoplásica, não fisiológica.\",null,\"O “apenas” derruba: também há hiperplasia.\"],\n\"Gestação: cresce (hipertrofia + hiperplasia). Parto: encolhe (atrofia com apoptose).\"],\nc03:[[\"Não é obrigatória, e se evoluir tende a carcinoma escamoso, não adenocarcinoma.\",\"Surfactante é produzido pelos pneumócitos tipo II nos alvéolos, não pelo epitélio brônquico.\",null,\"Não é neoplasia e não envolve o tecido conjuntivo.\"],\n\"Metaplasia é uma troca: ganha resistência, perde função. O brônquio aguenta a fumaça, mas perde a “vassoura” (cílios) e o muco.\"],\nc04:[[null,\"Não há constrição permanente: as vênulas ficam mais permeáveis.\",\"Fibronectina é proteína de matriz, não vasodilatadora.\",\"Trombos oclusivos imediatos não são o evento inicial.\"],\n\"Primeiro o susto (contrai), depois a festa (dilata). A constrição dura só segundos.\"],\nc05:[[\"Linfócitos T citotóxicos são de resposta viral ou crônica.\",\"Fibroblastos aparecem no reparo.\",null,\"Eosinófilos são de alergia e parasitose.\"],\n\"Piogênico = gera pus = neutrófilo.\"],\nc06:[[\"A fibrinosa tem fibrina em superfícies como pericárdio e pleura, não pus.\",null,\"A serosa tem líquido ralo. E transudato nem é inflamatório.\",\"Úlcera é defeito na superfície, não coleção fechada.\"],\n\"Abscesso = pus preso numa bolsa. Supurativa = pus.\"],\nc07:[[\"Fibrina não sofre metaplasia.\",\"Fibrina não se transforma em colesterol.\",null,\"Calcificação pode aparecer tardiamente em áreas lesadas, mas não é o destino comum nem imediato.\"],\n\"Pouca fibrina: some (fibrinólise). Muita fibrina: vira cicatriz (organização) e deixa aderências.\"],\nc08:[[\"Proliferação de glândulas não é úlcera.\",null,\"Pseudomembrana é exsudato fibrinoso aderido à superfície (ex.: colite por C. difficile).\",\"Isso descreve um granuloma.\"],\n\"Úlcera = buraco na superfície (pele, mucosa). Abscesso = bolsa de pus fechada.\"],\nc09:[[null,\"Organização deixa cicatriz, não devolve o tecido normal.\",\"Esse desfecho não existe.\",\"Progressão para crônica acontece quando o agente persiste.\"],\n\"Resolução é o “Ctrl+Z” da inflamação: tudo volta como era.\"],\nc10:[[null,\"Eosinófilos e mastócitos podem aparecer, mas o “exclusivamente” deixa errada.\",\"Fibroblastos aparecem no reparo, e osteoclastos não são típicos.\",\"Neutrófilos são a marca da inflamação aguda.\"],\n\"Crônica = LPM: Linfócitos, Plasmócitos e Macrófagos.\"],\nc11:[[\"Necrose fibrinoide isolada é típica de vasculites, não de granuloma.\",null,\"Neutrófilos com exsudato purulento são inflamação supurativa.\",\"Mastócitos e eosinófilos em torno de vasos não formam granuloma.\"],\n\"Granuloma = bolinha de macrófagos epitelioides + células gigantes + coroa de linfócitos.\"],\nc12:[[null,\"Gangrena é necrose de membros por isquemia.\",\"Necrose gordurosa ocorre no pâncreas e na mama.\",\"Necrose liquefativa ocorre em abscessos e no cérebro.\"],\n\"Caseosa = queijo = tuberculose. “A tuberculose come queijo”.\"],\nc13:[[\"O granuloma de corpo estranho não tem necrose caseosa.\",\"O Robbins distingue claramente os dois tipos.\",null,\"Granulomas imunológicos têm células gigantes, e não são feitos de neutrófilos.\"],\n\"Corpo estranho = macrófago sem imunologia (material inerte). Imunológico = macrófago comandado pela célula T (ex.: tuberculose).\"],\nc14:[[\"Prurido e vesículas são sinais de doenças de pele específicas.\",\"Febre e leucocitose são manifestações sistêmicas, não os sinais locais clássicos.\",null,\"Isso descreve choque.\"],\n\"Os quatro de Celsus rimam: rubOR, calOR, tumOR, dOR. Virchow acrescentou a perda de função.\"],\nc15:[[\"Há diferença mensurável: proteínas, densidade e células.\",null,\"O transudato é pobre em células.\",\"Queda da pressão oncótica gera transudato, não exsudato.\"],\n\"EXsudato: EXtravasa tudo (proteína e célula) porque o vaso “furou”. TRANSudato: só o líquido atravessa um vaso íntegro.\"],\nc16:[[\"Sem oxigênio não há aumento de mitocôndrias, e o glicogênio é CONSUMIDO na glicólise anaeróbia.\",null,\"Reparo não é consequência imediata.\",\"Não existe conversão em tecido adiposo.\"],\n\"Sem O₂ = sem ATP. Tudo o que vem depois (edema celular, acidose, queda da síntese de proteínas) é consequência da falta de ATP.\"],\nc18:[[null,\"Há diferença clara de causa e de local.\",\"PTH elevado está ligado à calcificação metastática.\",\"Valvas lesionadas calcificam de forma distrófica.\"],\n\"DIStrófica = tecido DOENTE, cálcio normal. METAstática = tecido normal, cálcio ALTO no sangue que se “espalha”.\"],\nc19:[[\"Necrose caseosa com cavitação descreve tuberculose.\",\"Não há neoplasia.\",null,\"Neutrófilos e liquefação em cavidade fechada descrevem empiema ou abscesso.\"],\n\"Fibrinogênio é molécula grande: só sai com vaso bem lesado. Depois, ou a fibrina some (resolução) ou vira cicatriz com aderências.\"],\nc20:[[\"Músculo não sofre metaplasia escamosa, e há infiltrado inflamatório.\",\"Na úlcera crônica há sinais de reparo, com tecido de granulação.\",null,\"Não há transformação maligna imediata.\"],\n\"Úlcera crônica tem camadas: fundo com neutrófilos, meio com tecido de granulação e borda com inflamação crônica e fibrose.\"]\n};\n\n/* =========================================================\n   ONDE ESTUDAR NO ROBBINS (capítulo e seção de cada questão)\n   ========================================================= */\nconst CHAPTERS = {\n  1: \"Cap. 1, Respostas celulares ao estresse: adaptação, lesão e morte\",\n  2: \"Cap. 2, Inflamação aguda e crônica\",\n  3: \"Cap. 3, Renovação, regeneração e reparo dos tecidos\"\n};\n/* [capítulo, nome da seção, página inicial no PDF da 8ª edição] */\nconst SEC = {\n  hipertrofia:[1,\"Hipertrofia\",35], hiperplasia:[1,\"Hiperplasia\",39], atrofia:[1,\"Atrofia\",41], metaplasia:[1,\"Metaplasia\",44],\n  atp:[1,\"Mecanismos da lesão celular: depleção de ATP\",66], apoptose:[1,\"Apoptose\",88], autofagia:[1,\"Autofagia\",106],\n  pigmentos:[1,\"Acúmulos intracelulares: pigmentos\",118], calcificacao:[1,\"Calcificação patológica\",122],\n  historia:[2,\"Visão geral da inflamação: destaques históricos\",140], vascular:[2,\"Reações dos vasos sanguíneos na inflamação aguda\",145],\n  recrutamento:[2,\"Reações dos leucócitos: recrutamento\",150], reconhecimento:[2,\"Reconhecimento dos micro-organismos e tecidos mortos\",158],\n  remocao:[2,\"Remoção dos agentes agressores\",160], ativacao:[2,\"Outras respostas funcionais dos leucócitos ativados\",165],\n  termino:[2,\"Término da resposta inflamatória aguda\",171], aminas:[2,\"Mediadores derivados de células: aminas vasoativas\",175],\n  araquidonico:[2,\"Metabólitos do ácido araquidônico\",176], complemento:[2,\"Sistema complemento\",188],\n  cininas:[2,\"Sistemas da coagulação e das cininas\",190], resultados:[2,\"Resultados da inflamação aguda\",194],\n  serosa:[2,\"Padrões morfológicos: inflamação serosa\",197], fibrinosa:[2,\"Padrões morfológicos: inflamação fibrinosa\",198],\n  supurativa:[2,\"Inflamação supurativa ou purulenta: abscessos\",199], ulceras:[2,\"Padrões morfológicos: úlceras\",200],\n  causas_cronica:[2,\"Causas da inflamação crônica\",203], morf_cronica:[2,\"Inflamação crônica: características morfológicas\",204],\n  macrofagos:[2,\"Participação dos macrófagos na inflamação crônica\",206], outras_celulas:[2,\"Outras células na inflamação crônica\",210],\n  granuloma:[2,\"Inflamação granulomatosa\",213], sistemicos:[2,\"Efeitos sistêmicos da inflamação\",216],\n  fatores:[3,\"Fatores de crescimento\",244], regeneracao:[3,\"Mecanismos de regeneração dos tecidos e órgãos\",258],\n  hepatica:[3,\"Regeneração hepática\",259], reparo:[3,\"Cura por reparo, formação de cicatriz e fibrose\",273],\n  angiogenese:[3,\"Mecanismos da angiogênese\",274], fibrose:[3,\"Fibrose\",290]\n};\n/* seção de cada questão; \":N\" indica a página exata quando o ponto está mais adiante na seção */\nconst REF = {\n  a01:\"hipertrofia\", a02:\"metaplasia\", a03:\"recrutamento\", a04:\"aminas\", a05:\"granuloma\", a06:\"vascular\", a07:\"macrofagos\", a08:\"recrutamento:152\", a09:\"atrofia\", a10:\"complemento\",\n  b01:\"hipertrofia\", b02:\"atrofia:43\", b03:\"metaplasia\", b04:\"hiperplasia\", b05:\"hipertrofia:38\", b06:\"metaplasia\", b07:\"pigmentos\", b08:\"hepatica\", b09:\"autofagia\", b10:\"hipertrofia:36\",\n  b11:\"vascular:146\", b12:\"vascular:147\", b13:\"recrutamento:152\", b14:\"recrutamento:155\", b15:\"remocao\", b16:\"serosa\", b17:\"cininas\", b18:\"remocao\", b19:\"sistemicos\", b20:\"termino\",\n  b21:\"recrutamento:157\", b22:\"supurativa\", b23:\"ulceras\", b24:\"remocao:163\", b25:\"sistemicos\", b26:\"morf_cronica\", b27:\"ativacao\", b28:\"ativacao\", b29:\"granuloma\", b30:\"granuloma\",\n  b31:\"outras_celulas:211\", b32:\"fibrose\", b33:\"granuloma:214\", b34:\"outras_celulas:211\", b35:\"fatores:245\", b36:\"reconhecimento:159\", b37:\"outras_celulas\", b38:\"complemento\", b39:\"araquidonico\", b40:\"causas_cronica\",\n  b41:\"resultados\", b42:\"angiogenese\", b43:\"remocao:163\", b44:\"recrutamento:152\", b45:\"fibrinosa\", b46:\"apoptose\", b47:\"sistemicos:217\", b48:\"granuloma\", b49:\"cininas\", b50:\"metaplasia:45\",\n  c01:\"regeneracao\", c02:\"hipertrofia\", c03:\"metaplasia\", c04:\"vascular:146\", c05:\"recrutamento:157\", c06:\"supurativa\", c07:\"fibrinosa\", c08:\"ulceras\", c09:\"resultados\", c10:\"morf_cronica\",\n  c11:\"granuloma\", c12:\"granuloma\", c13:\"granuloma:214\", c14:\"historia\", c15:\"vascular\", c16:\"atp\", c18:\"calcificacao\", c19:\"fibrinosa\", c20:\"ulceras\"\n};\nconst REF_NOTE = {\n  b18: \"As NETs não aparecem na 8ª edição (o tema entrou nas edições mais novas). A seção indicada é a mais próxima: como o neutrófilo mata micro-organismos.\"\n};\n\nfunction refParts(id){\n  const [key, pg] = (REF[id] || \"\").split(\":\");\n  const s = SEC[key];\n  if (!s) return null;\n  return { ch: s[0], name: s[1], page: pg ? +pg : s[2] };\n}\n\nfunction refHTML(id){\n  const r = refParts(id);\n  if (!r) return \"\";\n  const note = REF_NOTE[id] ? `<div class=\"refnote\">${REF_NOTE[id]}</div>` : \"\";\n  return `<div class=\"ref\"><span class=\"book\" aria-hidden=\"true\"></span><div>\n    <div class=\"eh\">Onde está no Robbins</div>\n    <b>${CHAPTERS[r.ch]}</b>, seção “${r.name}”, <b>p. ${r.page}</b>.${note}</div></div>`;\n}\n\nfunction robbinsMapHTML(){\n  const count = {};\n  QUESTIONS.forEach(q => { const k = (REF[q[0]] || \"\").split(\":\")[0]; count[k] = (count[k] || 0) + 1; });\n  const block = ch => Object.keys(SEC).filter(k => SEC[k][0] === ch && count[k])\n    .map(k => `<li><span>${SEC[k][1]} <em>p. ${SEC[k][2]}</em></span><b>${count[k]} ${count[k] === 1 ? \"questão\" : \"questões\"}</b></li>`).join(\"\");\n  return `<details class=\"rmap\">\n    <summary>Ver quais seções do Robbins as questões cobrem</summary>\n    <h3>${CHAPTERS[1]}</h3><ul>${block(1)}</ul>\n    <h3>${CHAPTERS[2]}</h3><ul>${block(2)}</ul>\n    <h3>${CHAPTERS[3]}</h3><ul>${block(3)}</ul>\n    <p class=\"note\">Robbins &amp; Cotran, Patologia: Bases Patológicas das Doenças, 8ª edição. As páginas são as do PDF do livro (parte 1).</p>\n  </details>`;\n}\n\n/* =========================================================\n   REVISÃO ESPAÇADA (estilo Anki, simplificado)\n   ========================================================= */\nconst KEY = \"patologia-n1-srs-v1\";\nconst DAY = 86400000;\nconst MIN = 60000;\nlet memoryStore = {};\nfunction load(){ try{ const raw = localStorage.getItem(KEY); return raw ? JSON.parse(raw) : {}; }catch(e){ return memoryStore; } }\nfunction save(){ try{ localStorage.setItem(KEY, JSON.stringify(state)); }catch(e){ memoryStore = state; } }\nlet state = load();\n\nfunction blank(){ return { r:0, e:2.5, i:0, d:0, l:0, n:0 }; }\n\nfunction nextDays(s, grade){\n  if (grade === \"hard\") return s.r === 0 ? 1 : Math.max(s.i + 1, Math.round(s.i * 1.2));\n  if (grade === \"good\") return s.r === 0 ? 2 : Math.max(s.i + 1, Math.round(s.i * s.e));\n  if (grade === \"easy\") return s.r === 0 ? 4 : Math.max(s.i + 2, Math.round(s.i * s.e * 1.3));\n  return 0;\n}\n\nfunction schedule(id, grade, customDays){\n  const s = Object.assign(blank(), state[id] || {});\n  const now = Date.now();\n  if (grade === \"custom\"){\n    if (customDays === 0){ s.d = now + 10 * MIN; }\n    else { s.i = customDays; s.r += 1; s.d = now + customDays * DAY; }\n  } else if (grade === \"again\"){\n    s.e = Math.max(1.3, s.e - 0.2); s.i = 0; s.r = 0; s.l += 1; s.d = now + 10 * MIN;\n  } else {\n    const days = nextDays(s, grade);\n    if (grade === \"hard\") s.e = Math.max(1.3, s.e - 0.15);\n    if (grade === \"easy\") s.e = s.e + 0.15;\n    s.i = days; s.r += 1; s.d = now + days * DAY;\n  }\n  s.n += 1;\n  state[id] = s; save();\n}\n\nfunction fmtDays(d){\n  if (d <= 1) return \"1 dia\";\n  if (d < 30) return d + \" dias\";\n  const m = Math.round(d / 30);\n  if (m < 12) return m === 1 ? \"1 mês\" : m + \" meses\";\n  const y = Math.round(d / 365);\n  return y === 1 ? \"1 ano\" : y + \" anos\";\n}\nfunction fmtUntil(ts){\n  const diff = ts - Date.now();\n  if (diff <= 0) return \"agora\";\n  if (diff < 60 * MIN) return \"em \" + Math.max(1, Math.round(diff / MIN)) + \" min\";\n  if (diff < DAY) return \"em \" + Math.round(diff / (60 * MIN)) + \" h\";\n  return \"em \" + fmtDays(Math.round(diff / DAY));\n}\n\nfunction cardsOf(topic){ return topic === \"all\" ? QUESTIONS : QUESTIONS.filter(q => q[1] === topic); }\n\nfunction statsOf(topic){\n  const now = Date.now();\n  let novas = 0, revisar = 0, emdia = 0, next = Infinity;\n  cardsOf(topic).forEach(q => {\n    const s = state[q[0]];\n    if (!s) novas++;\n    else if (s.d <= now) revisar++;\n    else { emdia++; next = Math.min(next, s.d); }\n  });\n  return { novas, revisar, emdia, next, total: cardsOf(topic).length };\n}\n\nfunction shuffle(arr){ const a = arr.slice(); for (let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }\n\n/* progresso: dominada = 3 acertos seguidos; 1 e 2 acertos contam 1/3 e 2/3 */\nfunction progressOf(topic){\n  const cards = cardsOf(topic);\n  let sum = 0, dom = 0, prog = 0;\n  cards.forEach(q => {\n    const s = state[q[0]];\n    if (!s) return;\n    const w = Math.min(s.r, 3) / 3;\n    sum += w;\n    if (s.r >= 3) dom++; else prog++;\n  });\n  return { pct: Math.round(sum / cards.length * 100), dom, prog, novas: cards.length - dom - prog };\n}\n\nfunction progHTML(p, from){\n  const full = p.pct >= 100;\n  const gain = from != null && p.pct > from ? `<span class=\"gain\">+${p.pct - from} pontos nesta sessão</span>` : \"\";\n  return `<div class=\"prog${full ? \" full\" : \"\"}\">\n    <div class=\"prog-head\">\n      <b data-to=\"${p.pct}\" data-from=\"${from != null ? from : 0}\">${from != null ? from : 0}%</b>\n      <span class=\"lbl\">${full ? \"dominado!\" : \"aprendido\"}</span>\n      ${gain}\n      <span class=\"det\">${p.dom} ${p.dom === 1 ? \"dominada\" : \"dominadas\"}, ${p.prog} em progresso</span>\n    </div>\n    <div class=\"track\" role=\"progressbar\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"${p.pct}\" aria-label=\"Percentual aprendido\">\n      <i class=\"fill\" style=\"width:${from != null ? from : 0}%\" data-w=\"${p.pct}\"></i>\n    </div>\n  </div>`;\n}\n\nfunction animateBars(){\n  const reduce = window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  const fills = app.querySelectorAll(\".fill[data-w]\");\n  const nums = app.querySelectorAll(\".prog-head b[data-to]\");\n  if (reduce){\n    fills.forEach(f => f.style.width = f.dataset.w + \"%\");\n    nums.forEach(n => n.textContent = n.dataset.to + \"%\");\n    return;\n  }\n  requestAnimationFrame(() => requestAnimationFrame(() => {\n    fills.forEach(f => f.style.width = f.dataset.w + \"%\");\n  }));\n  const t0 = performance.now(), dur = 1100;\n  const step = now => {\n    const k = Math.min(1, (now - t0) / dur);\n    const e = 1 - Math.pow(1 - k, 3);\n    nums.forEach(n => {\n      const a = +n.dataset.from, b = +n.dataset.to;\n      n.textContent = Math.round(a + (b - a) * e) + \"%\";\n    });\n    if (k < 1) requestAnimationFrame(step);\n  };\n  requestAnimationFrame(step);\n}\n\n/* =========================================================\n   TELAS\n   ========================================================= */\nconst app = document.getElementById(\"app\");\nconst LETTERS = [\"A\",\"B\",\"C\",\"D\",\"E\"];\nlet session = null;\nlet view = \"home\";\n\n/* pequenas “lâminas” desenhadas em SVG para cada assunto */\nfunction tissueSVG(kind){\n  const nuclei = (pts, r) => pts.map(p => `<circle cx=\"${p[0]}\" cy=\"${p[1]}\" r=\"${r}\" fill=\"var(--hema)\" opacity=\".85\"/>`).join(\"\");\n  if (kind === 0){ // adaptação: células grandes e pequenas lado a lado\n    return `<svg class=\"tissue\" viewBox=\"0 0 135 100\" aria-hidden=\"true\">\n      <ellipse cx=\"67\" cy=\"50\" rx=\"62\" ry=\"44\" fill=\"var(--eosin-soft)\"/>\n      <g fill=\"none\" stroke=\"var(--eosin)\" stroke-width=\"1.4\" opacity=\".75\">\n        <rect x=\"18\" y=\"26\" width=\"20\" height=\"20\" rx=\"4\"/><rect x=\"18\" y=\"50\" width=\"20\" height=\"20\" rx=\"4\"/>\n        <rect x=\"44\" y=\"18\" width=\"34\" height=\"34\" rx=\"6\"/><rect x=\"44\" y=\"56\" width=\"34\" height=\"26\" rx=\"6\"/>\n        <rect x=\"84\" y=\"30\" width=\"16\" height=\"16\" rx=\"3\"/><rect x=\"84\" y=\"50\" width=\"16\" height=\"16\" rx=\"3\"/><rect x=\"104\" y=\"40\" width=\"14\" height=\"14\" rx=\"3\"/>\n      </g>\n      ${nuclei([[28,36],[28,60],[61,35],[61,69],[92,38],[92,58],[111,47]],3.4)}\n    </svg>`;\n  }\n  if (kind === 1){ // aguda: vaso com neutrófilos saindo\n    return `<svg class=\"tissue\" viewBox=\"0 0 135 100\" aria-hidden=\"true\">\n      <ellipse cx=\"67\" cy=\"50\" rx=\"62\" ry=\"44\" fill=\"var(--eosin-soft)\"/>\n      <path d=\"M8 44 Q67 30 127 44 L127 58 Q67 44 8 58 Z\" fill=\"none\" stroke=\"var(--eosin)\" stroke-width=\"1.6\" opacity=\".8\"/>\n      <g fill=\"var(--hema)\" opacity=\".9\">\n        <circle cx=\"30\" cy=\"48\" r=\"2.2\"/><circle cx=\"34\" cy=\"50\" r=\"2.2\"/><circle cx=\"32\" cy=\"53\" r=\"2.2\"/>\n        <circle cx=\"62\" cy=\"62\" r=\"2.2\"/><circle cx=\"66\" cy=\"64\" r=\"2.2\"/><circle cx=\"64\" cy=\"67\" r=\"2.2\"/>\n        <circle cx=\"86\" cy=\"72\" r=\"2.2\"/><circle cx=\"90\" cy=\"74\" r=\"2.2\"/><circle cx=\"88\" cy=\"77\" r=\"2.2\"/>\n        <circle cx=\"50\" cy=\"22\" r=\"2.2\"/><circle cx=\"54\" cy=\"24\" r=\"2.2\"/><circle cx=\"52\" cy=\"27\" r=\"2.2\"/>\n        <circle cx=\"100\" cy=\"26\" r=\"2.2\"/><circle cx=\"104\" cy=\"28\" r=\"2.2\"/><circle cx=\"102\" cy=\"31\" r=\"2.2\"/>\n      </g>\n    </svg>`;\n  }\n  // crônica: granuloma\n  return `<svg class=\"tissue\" viewBox=\"0 0 135 100\" aria-hidden=\"true\">\n    <ellipse cx=\"67\" cy=\"50\" rx=\"62\" ry=\"44\" fill=\"var(--eosin-soft)\"/>\n    <circle cx=\"67\" cy=\"50\" r=\"30\" fill=\"var(--eosin)\" opacity=\".28\"/>\n    <circle cx=\"67\" cy=\"50\" r=\"12\" fill=\"var(--card)\" opacity=\".85\"/>\n    <g fill=\"var(--hema)\" opacity=\".55\">\n      <ellipse cx=\"52\" cy=\"40\" rx=\"3.6\" ry=\"2\" transform=\"rotate(-30 52 40)\"/><ellipse cx=\"82\" cy=\"40\" rx=\"3.6\" ry=\"2\" transform=\"rotate(30 82 40)\"/>\n      <ellipse cx=\"50\" cy=\"60\" rx=\"3.6\" ry=\"2\" transform=\"rotate(30 50 60)\"/><ellipse cx=\"84\" cy=\"60\" rx=\"3.6\" ry=\"2\" transform=\"rotate(-30 84 60)\"/>\n      <ellipse cx=\"67\" cy=\"30\" rx=\"3.6\" ry=\"2\"/><ellipse cx=\"67\" cy=\"71\" rx=\"3.6\" ry=\"2\"/>\n    </g>\n    <g fill=\"var(--hema)\" opacity=\".95\">\n      ${[[25,50],[30,30],[30,70],[45,18],[45,82],[67,13],[67,87],[89,18],[89,82],[104,30],[104,70],[109,50],[20,40],[20,60],[114,40],[114,60]].map(p=>`<circle cx=\"${p[0]}\" cy=\"${p[1]}\" r=\"2.6\"/>`).join(\"\")}\n    </g>\n  </svg>`;\n}\n\nfunction statBlock(st){\n  return `<div class=\"stats\">\n    <div class=\"stat new\"><b>${st.novas}</b><span>novas</span></div>\n    <div class=\"stat due\"><b>${st.revisar}</b><span>para revisar</span></div>\n    <div class=\"stat ok\"><b>${st.emdia}</b><span>em dia</span></div>\n  </div>`;\n}\n\nfunction renderHome(){\n  view = \"home\"; session = null;\n  const slides = Object.keys(TOPICS).map(k => {\n    const t = TOPICS[k], st = statsOf(k);\n    return `<button class=\"slide\" data-topic=\"${k}\" aria-label=\"Estudar ${t.name}\">\n      <div class=\"label\">\n        <div><h2>${t.name}</h2><div class=\"total\">${st.total} questões</div></div>\n        ${statBlock(st)}\n      </div>\n      <div class=\"glass\">${tissueSVG(t.tissue)}<span class=\"go\">Estudar</span></div>\n      ${progHTML(progressOf(k))}\n    </button>`;\n  }).join(\"\");\n  const all = statsOf(\"all\");\n  app.innerHTML = `\n    <header class=\"intro\">\n      <h1>Patologia Geral N1</h1>\n      <p>As ${QUESTIONS.length} questões das listas do professor, separadas por assunto, com correção comentada e revisão espaçada. Cada comentário é baseado no Robbins &amp; Cotran (8ª edição) e indica capítulo, seção e página onde a resposta está.</p>\n    </header>\n    <div class=\"how\">\n      <strong>Como funciona:</strong> responda, veja o comentário e diga se foi difícil, bom ou fácil. Quanto mais fácil, mais tempo a questão demora para voltar. Se preferir, você mesmo escolhe quando ela volta. Se errar, ela volta ainda nesta sessão. A barra de cada assunto mostra quanto você já aprendeu: uma questão fica dominada depois de 3 acertos seguidos em revisões. Seu progresso fica salvo neste navegador.\n    </div>\n    <div id=\"groupSlot\">${groupEntryHTML()}</div>\n    ${robbinsMapHTML()}\n    <div class=\"slides\">\n      ${slides}\n      <button class=\"slide all\" data-topic=\"all\" aria-label=\"Estudar todos os assuntos misturados\">\n        <div class=\"label\">\n          <div><h2>Todos os assuntos misturados</h2><div class=\"total\">${all.total} questões</div></div>\n          ${statBlock(all)}\n        </div>\n        ${progHTML(progressOf(\"all\"))}\n      </button>\n    </div>\n    <div class=\"backup-row\">\n      <button class=\"ghost\" id=\"bkSave\">Salvar backup do progresso</button>\n      <button class=\"ghost\" id=\"bkLoad\">Restaurar backup</button>\n    </div>\n    <div class=\"footer\">\n      <span>Progresso salvo só neste aparelho e navegador. Faça backup de vez em quando.</span>\n      <button class=\"linkbtn\" id=\"reset\">Zerar meu progresso</button>\n    </div>`;\n  app.querySelectorAll(\".slide\").forEach(b => b.addEventListener(\"click\", () => startSession(b.dataset.topic, false)));\n  document.getElementById(\"bkSave\").addEventListener(\"click\", renderBackupSave);\n  document.getElementById(\"bkLoad\").addEventListener(\"click\", renderBackupLoad);\n  document.getElementById(\"reset\").addEventListener(\"click\", () => {\n    if (confirm(\"Apagar todo o seu progresso? Todas as questões voltam a ser novas.\")){ state = {}; save(); renderHome(); }\n  });\n  refreshGroupEntry();\n  animateBars();\n  window.scrollTo(0, 0);\n}\n\nfunction topicName(topic){ return topic === \"all\" ? \"Todos os assuntos\" : TOPICS[topic].name; }\n\nfunction startSession(topic, ahead){\n  const now = Date.now();\n  const cards = cardsOf(topic);\n  let queue;\n  if (ahead){\n    queue = cards.slice().sort((a, b) => (state[a[0]] ? state[a[0]].d : 0) - (state[b[0]] ? state[b[0]].d : 0));\n  } else {\n    const due = cards.filter(q => state[q[0]] && state[q[0]].d <= now).sort((a, b) => state[a[0]].d - state[b[0]].d);\n    const fresh = shuffle(cards.filter(q => !state[q[0]]));\n    queue = due.concat(fresh);\n  }\n  if (!queue.length){ renderEmpty(topic); return; }\n  session = { topic, queue, total: queue.length, done: 0, right: 0, wrong: 0, answered: false, firstTry: {}, startPct: progressOf(topic).pct };\n  renderCard();\n}\n\nfunction renderEmpty(topic){\n  view = \"empty\";\n  const st = statsOf(topic);\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>${topicName(topic)}</h3></div></div>\n    <div class=\"done\">\n      <h2>Nada para revisar agora</h2>\n      <p>Você está em dia com ${topicName(topic).toLowerCase()}.</p>\n      <p>Próxima revisão ${isFinite(st.next) ? fmtUntil(st.next) : \"quando quiser\"}.</p>\n      <div class=\"row\">\n        <button class=\"ghost\" id=\"back2\">Voltar aos assuntos</button>\n        <button class=\"primary\" id=\"ahead\">Revisar mesmo assim</button>\n      </div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"back2\").onclick = renderHome;\n  document.getElementById(\"ahead\").onclick = () => startSession(topic, true);\n}\n\n/* embaralha as alternativas a cada aparição; \"todas/nenhuma das alternativas\" fica no fim */\nconst lastOrder = {};\nconst PINNED = /todas as alternativas|nenhuma das alternativas|todas as anteriores|nenhuma das anteriores/i;\nfunction optionOrder(q){\n  const idx = q[4].map((_, i) => i);\n  const pinned = idx.filter(i => PINNED.test(q[4][i]));\n  const free = idx.filter(i => !PINNED.test(q[4][i]));\n  const prev = (lastOrder[q[0]] || idx).join(\",\");\n  let order;\n  for (let t = 0; t < 8; t++){\n    order = shuffle(free).concat(pinned);\n    if (order.join(\",\") !== prev && free.length > 1) break;\n  }\n  lastOrder[q[0]] = order;\n  return order;\n}\n\nfunction renderCard(){\n  view = \"card\";\n  const q = session.queue[0];\n  session.answered = false;\n  session.order = optionOrder(q);\n  const pct = Math.round(session.done / (session.done + session.queue.length) * 100);\n  const s = state[q[0]];\n  const tag = !s ? \"Nova\" : (s.r === 0 ? \"Reaprendendo\" : \"Revisão\");\n  app.innerHTML = `\n    <div class=\"topbar\">\n      <button class=\"back\" id=\"back\">Voltar</button>\n      <div class=\"t\"><h3>${topicName(session.topic)}</h3><div>${session.queue.length} ${session.queue.length === 1 ? \"questão restante\" : \"questões restantes\"}</div></div>\n    </div>\n    <div class=\"bar\"><i style=\"width:${pct}%\"></i></div>\n    <article class=\"qcard\">\n      <div class=\"src\"><span>${q[2]}</span><span class=\"tag\">${tag}</span></div>\n      <p class=\"qtext\">${q[3]}</p>\n      <div class=\"opts\" role=\"group\" aria-label=\"Alternativas\">\n        ${session.order.map((oi, pos) => `<button class=\"opt\" data-i=\"${oi}\"><span class=\"l\">${LETTERS[pos]}</span><span>${q[4][oi]}</span></button>`).join(\"\")}\n      </div>\n      <div class=\"fb\" id=\"fb\" aria-live=\"polite\"></div>\n    </article>\n    <div class=\"keys\">Atalhos: <kbd>A</kbd> a <kbd>D</kbd> para responder</div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  app.querySelectorAll(\".opt\").forEach(b => b.addEventListener(\"click\", () => answer(+b.dataset.i)));\n  window.scrollTo(0, 0);\n}\n\nfunction answer(i){\n  if (session.answered) return;\n  session.answered = true;\n  const q = session.queue[0];\n  const correct = i === q[5];\n  if (!(q[0] in session.firstTry)) session.firstTry[q[0]] = correct;\n  app.querySelectorAll(\".opt\").forEach(b => {\n    const k = +b.dataset.i;\n    b.disabled = true;\n    if (k === q[5]) b.classList.add(\"right\");\n    else if (k === i) b.classList.add(\"wrong\");\n    else b.classList.add(\"dim\");\n  });\n  addReasons(q, i);\n  const fb = document.getElementById(\"fb\");\n  const keys = document.querySelector(\".keys\");\n  if (correct){\n    session.right++;\n    const s = Object.assign(blank(), state[q[0]] || {});\n    const streak = state[q[0]] ? state[q[0]].r + 1 : 1;\n    fb.innerHTML = `\n      <div class=\"verdict ok\">Acertou!</div>\n      ${streak >= 2 ? cheerHTML(streak) : \"\"}\n      ${explainHTML(q)}\n      <div class=\"rate\">\n        <p>Como foi responder essa?</p>\n        <div class=\"rbtns\">\n          <button class=\"rbtn hard\" data-g=\"hard\">Difícil<small>volta em ${fmtDays(nextDays(s, \"hard\"))}</small></button>\n          <button class=\"rbtn good\" data-g=\"good\">Bom<small>volta em ${fmtDays(nextDays(s, \"good\"))}</small></button>\n          <button class=\"rbtn easy\" data-g=\"easy\">Fácil<small>volta em ${fmtDays(nextDays(s, \"easy\"))}</small></button>\n        </div>\n        ${customBlock()}\n      </div>`;\n    fb.querySelectorAll(\".rbtn\").forEach(b => b.addEventListener(\"click\", () => rate(b.dataset.g)));\n    bindCustom();\n    if (streak >= 2) burst(streak);\n    keys.innerHTML = `Atalhos: <kbd>1</kbd> difícil, <kbd>2</kbd> bom, <kbd>3</kbd> fácil`;\n  } else {\n    session.wrong++;\n    fb.innerHTML = `\n      <div class=\"verdict no\">Errou. A correta é a ${LETTERS[session.order.indexOf(q[5])]}.</div>\n      ${explainHTML(q)}\n      <button class=\"primary\" id=\"cont\">Continuar (ela volta daqui a pouco)</button>\n      ${customBlock()}`;\n    document.getElementById(\"cont\").addEventListener(\"click\", () => rate(\"again\"));\n    bindCustom();\n    keys.innerHTML = `Atalho: <kbd>Enter</kbd> para continuar`;\n  }\n}\n\nfunction pick(arr){ return arr[Math.floor(Math.random() * arr.length)]; }\n\nfunction cheerHTML(n){\n  let big, lvl;\n  if (n === 2){ big = pick([\"Acertou de novo!\", \"Segunda vez seguida!\", \"De novo! Está fixando.\"]); lvl = 2; }\n  else if (n === 3){ big = pick([\"Três seguidas! Essa já é sua.\", \"Terceira vez! Muito bom.\", \"Três de três!\"]); lvl = 3; }\n  else { big = n + \" acertos seguidos! \" + pick([\"Questão dominada.\", \"Na prova essa não escapa.\", \"Você está voando.\"]); lvl = 4; }\n  const sub = pick([\"A revisão espaçada está funcionando.\", \"Continue assim.\", \"É assim que o conteúdo fica na memória.\", \"Seu eu da prova agradece.\"]);\n  const dots = Array.from({ length: Math.min(n, 6) }, (_, i) => `<i style=\"animation-delay:${(0.08 * i + 0.15).toFixed(2)}s\"></i>`).join(\"\");\n  return `<div class=\"cheer lvl${lvl}\" role=\"status\">\n    <div class=\"dots\" aria-hidden=\"true\">${dots}</div>\n    <div><div class=\"big\">${big}</div><div class=\"sub\">${sub}</div></div>\n  </div>`;\n}\n\nfunction burst(n){\n  if (window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches) return;\n  const anchor = document.querySelector(\".cheer\") || document.querySelector(\".verdict\");\n  if (!anchor) return;\n  const r = anchor.getBoundingClientRect();\n  const x = r.left + Math.min(60, r.width / 2), y = r.top + r.height / 2;\n  const count = n === 2 ? 26 : n === 3 ? 42 : 60;\n  const reach = n === 2 ? 150 : n === 3 ? 210 : 270;\n  const colors = [\"var(--eosin)\", \"var(--eosin-soft)\", \"var(--hema)\", \"var(--hema-soft)\", \"#F2B6CC\"];\n  const box = document.createElement(\"div\");\n  box.className = \"burst\";\n  for (let i = 0; i < count; i++){\n    const a = Math.random() * Math.PI * 2;\n    const d = reach * (0.45 + Math.random() * 0.55);\n    const size = 6 + Math.random() * (n >= 3 ? 12 : 9);\n    const b = document.createElement(\"span\");\n    b.className = \"bit\" + (size > 11 ? \" cell\" : \"\");\n    b.style.cssText = `--x:${x}px;--y:${y}px;--s:${size}px;--c:${pick(colors)};` +\n      `--dx:${Math.cos(a) * d}px;--dy:${Math.sin(a) * d + 40}px;--r:${Math.round(Math.random() * 360)}deg;` +\n      `--t:${0.9 + Math.random() * 0.6}s;animation-delay:${Math.random() * 0.12}s`;\n    box.appendChild(b);\n  }\n  document.body.appendChild(box);\n  setTimeout(() => box.remove(), 1900);\n}\n\nfunction explainHTML(q, order){\n  order = order || session.order;\n  const L = LETTERS[order.indexOf(q[5])];\n  const ex = EXTRA[q[0]];\n  return `<div class=\"expl\"><div class=\"eh\">Por que a ${L} está certa</div>${q[6]}</div>\n      ${ex && ex[1] ? `<div class=\"tip\"><div class=\"th\">Macete</div>${ex[1]}</div>` : \"\"}\n      ${refHTML(q[0])}`;\n}\n\nfunction addReasons(q, chosen){\n  const ex = EXTRA[q[0]];\n  if (!ex) return;\n  app.querySelectorAll(\".opt\").forEach(b => {\n    const k = +b.dataset.i;\n    if (k === q[5] || !ex[0][k]) return;\n    const d = document.createElement(\"span\");\n    d.className = \"why\";\n    d.innerHTML = (k === chosen ? \"<b>Você marcou.</b> \" : \"\") + ex[0][k];\n    b.lastElementChild.appendChild(d);\n  });\n}\n\nfunction customBlock(){\n  const opts = [[0,\"Ainda nesta sessão\"],[1,\"1 dia\"],[3,\"3 dias\"],[7,\"1 semana\"],[14,\"2 semanas\"],[30,\"1 mês\"]];\n  return `<details class=\"custom\">\n    <summary>Prefiro escolher quando ela volta</summary>\n    <div class=\"chips\">${opts.map(o => `<button class=\"chip\" data-d=\"${o[0]}\">${o[1]}</button>`).join(\"\")}</div>\n    <div class=\"own\">\n      <label for=\"ownDays\">Ou digite:</label>\n      <input id=\"ownDays\" type=\"number\" min=\"1\" max=\"365\" inputmode=\"numeric\" placeholder=\"10\">\n      <span>dias</span>\n      <button class=\"chip\" id=\"ownGo\">Confirmar</button>\n      <span class=\"err\" id=\"ownErr\" hidden>Digite um número de 1 a 365.</span>\n    </div>\n  </details>`;\n}\n\nfunction bindCustom(){\n  app.querySelectorAll(\".chip[data-d]\").forEach(b => b.addEventListener(\"click\", () => rate(\"custom\", +b.dataset.d)));\n  const go = () => {\n    const n = parseInt(document.getElementById(\"ownDays\").value, 10);\n    if (!(n >= 1 && n <= 365)){ document.getElementById(\"ownErr\").hidden = false; return; }\n    rate(\"custom\", n);\n  };\n  document.getElementById(\"ownGo\").addEventListener(\"click\", go);\n  document.getElementById(\"ownDays\").addEventListener(\"keydown\", e => { if (e.key === \"Enter\"){ e.preventDefault(); go(); } });\n}\n\nfunction rate(grade, customDays){\n  const q = session.queue.shift();\n  schedule(q[0], grade, customDays);\n  const again = grade === \"again\" || (grade === \"custom\" && customDays === 0);\n  if (again){\n    const pos = Math.min(3, session.queue.length);\n    session.queue.splice(pos, 0, q);\n  } else {\n    session.done++;\n  }\n  if (session.queue.length) renderCard(); else renderEnd();\n}\n\nfunction renderEnd(){\n  view = \"end\";\n  const ids = Object.keys(session.firstTry);\n  const first = ids.filter(id => session.firstTry[id]).length;\n  const st = statsOf(session.topic);\n  app.innerHTML = `\n    <div class=\"done\">\n      <h2>Sessão concluída</h2>\n      <p>${topicName(session.topic)}</p>\n      <div class=\"score\">\n        <div class=\"a\"><b>${first}</b><span>certas de primeira</span></div>\n        <div class=\"e\"><b>${ids.length - first}</b><span>erradas de primeira</span></div>\n      </div>\n      ${progHTML(progressOf(session.topic), session.startPct)}\n      <p>Próxima revisão ${isFinite(st.next) ? fmtUntil(st.next) : \"quando quiser\"}.</p>\n      <div class=\"row\">\n        <button class=\"primary\" id=\"home\">Voltar aos assuntos</button>\n      </div>\n    </div>`;\n  document.getElementById(\"home\").onclick = renderHome;\n  animateBars();\n  window.scrollTo(0, 0);\n}\n\n/* =========================================================\n   BACKUP DO PROGRESSO\n   ========================================================= */\nconst BK_PREFIX = \"PATON1-\";\nconst VALID_IDS = new Set(QUESTIONS.map(q => q[0]));\n\nfunction encodeBackup(){\n  const rows = Object.keys(state).map(id => {\n    const s = state[id];\n    return [id, s.r, Math.round(s.e * 100), s.i, Math.round(s.d / MIN), s.l, s.n];\n  });\n  return BK_PREFIX + btoa(JSON.stringify(rows));\n}\n\nfunction decodeBackup(code){\n  const clean = (code || \"\").replace(/\\s+/g, \"\");\n  if (!clean.startsWith(BK_PREFIX)) throw new Error(\"formato\");\n  const rows = JSON.parse(atob(clean.slice(BK_PREFIX.length)));\n  if (!Array.isArray(rows)) throw new Error(\"formato\");\n  const out = {};\n  rows.forEach(r => {\n    if (!Array.isArray(r) || !VALID_IDS.has(r[0])) return;\n    out[r[0]] = { r: +r[1] || 0, e: (+r[2] || 250) / 100, i: +r[3] || 0, d: (+r[4] || 0) * MIN, l: +r[5] || 0, n: +r[6] || 0 };\n  });\n  return out;\n}\n\nfunction renderBackupSave(){\n  view = \"backup\";\n  const n = Object.keys(state).length;\n  if (!n){\n    app.innerHTML = `\n      <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Backup do progresso</h3></div></div>\n      <div class=\"panel\">\n        <h2>Ainda não há progresso</h2>\n        <p>Responda algumas questões e depois volte aqui para salvar o backup.</p>\n      </div>`;\n    document.getElementById(\"back\").onclick = renderHome;\n    return;\n  }\n  const code = encodeBackup();\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Backup do progresso</h3></div></div>\n    <div class=\"panel\">\n      <h2>Seu código de backup</h2>\n      <p>Ele guarda o progresso de ${n} ${n === 1 ? \"questão\" : \"questões\"}. Copie e guarde em um lugar seguro, como o app de notas ou uma mensagem para você mesmo no WhatsApp. Para recuperar, use “Restaurar backup” em qualquer navegador ou celular.</p>\n      <textarea id=\"code\" readonly aria-label=\"Código de backup\">${code}</textarea>\n      <div class=\"row\">\n        <button class=\"primary\" id=\"copy\">Copiar código</button>\n        <button class=\"ghost\" id=\"back2\">Voltar aos assuntos</button>\n      </div>\n      <div id=\"msg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"back2\").onclick = renderHome;\n  const ta = document.getElementById(\"code\");\n  const ok = () => { document.getElementById(\"msg\").innerHTML = `<div class=\"msg ok\">Código copiado. Agora cole em um lugar seguro.</div>`; };\n  const manual = () => {\n    ta.focus(); ta.setSelectionRange(0, ta.value.length);\n    let copied = false;\n    try { copied = document.execCommand(\"copy\"); } catch(e){}\n    if (copied) ok();\n    else document.getElementById(\"msg\").innerHTML = `<div class=\"msg bad\">Não deu para copiar automaticamente. O código já está selecionado: segure em cima dele e toque em Copiar.</div>`;\n  };\n  document.getElementById(\"copy\").onclick = () => {\n    if (navigator.clipboard && navigator.clipboard.writeText){\n      navigator.clipboard.writeText(code).then(ok, manual);\n    } else manual();\n  };\n}\n\nfunction renderBackupLoad(){\n  view = \"backup\";\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Restaurar backup</h3></div></div>\n    <div class=\"panel\">\n      <h2>Restaurar um backup</h2>\n      <p>Cole abaixo o código que começa com ${BK_PREFIX}. O progresso deste navegador será substituído pelo do backup.</p>\n      <textarea id=\"code\" aria-label=\"Cole aqui o código de backup\" placeholder=\"Cole o código aqui\"></textarea>\n      <div class=\"row\">\n        <button class=\"primary\" id=\"restore\">Restaurar progresso</button>\n        <button class=\"ghost\" id=\"back2\">Voltar aos assuntos</button>\n      </div>\n      <div id=\"msg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  document.getElementById(\"back2\").onclick = renderHome;\n  document.getElementById(\"restore\").onclick = () => {\n    const msg = document.getElementById(\"msg\");\n    let data;\n    try { data = decodeBackup(document.getElementById(\"code\").value); }\n    catch(e){ msg.innerHTML = `<div class=\"msg bad\">Esse código não é válido. Confira se copiou ele inteiro, começando por ${BK_PREFIX}.</div>`; return; }\n    const n = Object.keys(data).length;\n    if (!n){ msg.innerHTML = `<div class=\"msg bad\">Esse código não tem nenhuma questão salva.</div>`; return; }\n    if (Object.keys(state).length && !confirm(`Substituir o progresso deste navegador pelo backup (${n} questões)?`)) return;\n    state = data; save();\n    msg.innerHTML = `<div class=\"msg ok\">Progresso restaurado: ${n} ${n === 1 ? \"questão\" : \"questões\"}.</div>`;\n  };\n}\n\n/* =========================================================\n   MODO EM GRUPO (sala em tempo real)\n   Usa só \"presence\" da capacidade room: o líder publica a questão\n   atual na própria presença; quem entra depois recebe na hora.\n   ========================================================= */\nconst APP = \"pato1\";\nlet room = null, roomStatus = \"loading\"; // loading | ok | off\nlet group = null; // { code, role, name, topic, pool, idx, since, myAns, lastHost, ended }\nconst NAME_KEY = \"patologia-n1-nome\";\n\nfunction esc(s){ return String(s == null ? \"\" : s).replace(/[&<>\"']/g, c => ({ \"&\":\"&amp;\", \"<\":\"&lt;\", \">\":\"&gt;\", '\"':\"&quot;\", \"'\":\"&#39;\" }[c])); }\nfunction getName(){ try{ return localStorage.getItem(NAME_KEY) || \"\"; }catch(e){ return \"\"; } }\nfunction setName(n){ try{ localStorage.setItem(NAME_KEY, n); }catch(e){} }\nfunction newCode(){ const A = \"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\"; let c = \"\"; for (let i = 0; i < 4; i++) c += A[Math.floor(Math.random() * A.length)]; return c; }\nfunction cleanCode(s){ return String(s || \"\").toUpperCase().replace(/[^A-Z0-9]/g, \"\").slice(0, 4); }\nfunction pres(patch){ if (room) room.presence(patch).catch(() => {}); }\n\n/* Conexão com o servidor de salas do Cloudflare (mesmo formato usado pelo resto do código) */\nfunction makeCfRoom(){\n  let ws = null, code = null, want = null, myPeer = null, list = [], retry = 0, pingT = null, isOpen = false;\n  let mine = {};\n  const peerLs = [], connLs = [];\n  let snapshot = Object.freeze([]);\n  function build(){\n    snapshot = Object.freeze(list.map(x => Object.freeze({\n      peer: x.peer, isMe: x.peer === myPeer, sameTab: x.peer === myPeer,\n      presence: Object.freeze(Object.assign({}, x.presence || {}, { app: APP, sala: code }))\n    })));\n    peerLs.forEach(h => { try { h({ peers: snapshot }); } catch(e){} });\n  }\n  function setOpen(v){ if (isOpen !== v){ isOpen = v; connLs.forEach(h => { try { h(v); } catch(e){} }); } }\n  function send(){ if (ws && ws.readyState === 1) ws.send(JSON.stringify({ t: \"presence\", p: mine })); }\n  function open(){\n    const target = code;\n    const proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n    const sock = new WebSocket(proto + \"//\" + location.host + \"/ws/\" + target);\n    ws = sock;\n    sock.onopen = () => { retry = 0; setOpen(true); send(); clearInterval(pingT); pingT = setInterval(() => { try { sock.send(\"ping\"); } catch(e){} }, 30000); };\n    sock.onmessage = e => {\n      if (e.data === \"pong\") return;\n      let m; try { m = JSON.parse(e.data); } catch(err){ return; }\n      if (m.t === \"hello\"){ myPeer = m.peer; list = Array.isArray(m.peers) ? m.peers : []; build(); }\n      else if (m.t === \"peers\"){ list = Array.isArray(m.peers) ? m.peers : []; build(); }\n    };\n    sock.onclose = () => {\n      if (ws !== sock) return;\n      setOpen(false); clearInterval(pingT);\n      if (want === target){\n        const d = Math.min(8000, 500 * Math.pow(2, retry++));\n        setTimeout(() => { if (want === target && ws === sock) open(); }, d);\n      }\n    };\n  }\n  return {\n    presence(patch){\n      if (patch.sala === null){\n        want = null; code = null; mine = {}; myPeer = null; list = [];\n        const old = ws; ws = null; clearInterval(pingT); setOpen(false);\n        if (old){ try { old.close(1000, \"saiu\"); } catch(e){} }\n        build(); return Promise.resolve();\n      }\n      if (typeof patch.sala === \"string\" && patch.sala !== code){\n        const old = ws; ws = null;\n        if (old){ try { old.close(1000, \"trocou\"); } catch(e){} }\n        code = patch.sala; want = code; mine = {}; list = []; myPeer = null;\n        open();\n      }\n      for (const k in patch){\n        if (k === \"app\" || k === \"sala\") continue;\n        if (patch[k] === null) delete mine[k]; else mine[k] = patch[k];\n      }\n      send();\n      if (myPeer){\n        const me = { peer: myPeer, presence: Object.assign({}, mine) };\n        list = list.some(x => x.peer === myPeer) ? list.map(x => x.peer === myPeer ? me : x) : list.concat([me]);\n        build();\n      }\n      return Promise.resolve();\n    },\n    peers(){ return snapshot; },\n    connected(){ return true; },\n    onPeers(h){ peerLs.push(h); return () => {}; },\n    onConnection(h){ setTimeout(() => h(true), 0); return () => {}; }\n  };\n}\n\nconst roomReady = Promise.resolve(/^https?:$/.test(location.protocol) ? makeCfRoom() : null);\n\nroomReady.then(r => {\n  room = r;\n  if (!r){ roomStatus = \"off\"; refreshGroupEntry(); return; }\n  r.onConnection(c => { if (c) roomStatus = \"ok\"; refreshGroupEntry(); },\n                 () => { roomStatus = \"off\"; refreshGroupEntry(); if (view.startsWith(\"g-\")) renderGroup(); });\n  r.onPeers(() => {\n    if (view === \"g-lobby\") renderRoomList();\n    else if (view === \"g-room\") renderGroup();\n  }, () => { roomStatus = \"off\"; if (view.startsWith(\"g-\")) renderGroup(); });\n});\nsetTimeout(() => { if (roomStatus === \"loading\" && !(room && room.connected())){ roomStatus = room ? \"loading\" : \"off\"; refreshGroupEntry(); } }, 10000);\n\nfunction groupEntryHTML(){\n  const off = roomStatus === \"off\";\n  const sub = off\n    ? \"Funciona pelo link do site. No arquivo baixado, use o estudo individual abaixo.\"\n    : roomStatus === \"loading\" ? \"Conectando...\" : \"Crie uma sala ou entre com o código da turma. Todos veem a mesma questão ao mesmo tempo.\";\n  return `<button class=\"group-entry\" id=\"groupBtn\" ${off ? \"disabled\" : \"\"}>\n    <span class=\"gi\" aria-hidden=\"true\"><i></i><i></i><i></i></span>\n    <span><h2>Estudar em grupo</h2><p>${sub}</p></span>\n  </button>`;\n}\nfunction refreshGroupEntry(){\n  const el = document.getElementById(\"groupSlot\");\n  if (!el) return;\n  el.innerHTML = groupEntryHTML();\n  const b = document.getElementById(\"groupBtn\");\n  if (b && !b.disabled) b.onclick = renderLobby;\n}\n\nfunction peersInRoom(code){\n  if (!room) return [];\n  return room.peers().filter(p => p.presence && p.presence.app === APP && p.presence.sala === code && (p.presence.role === \"host\" || p.presence.role === \"member\"));\n}\nfunction hostPeer(code){\n  const hs = peersInRoom(code).filter(p => p.presence.role === \"host\" && typeof p.presence.qid === \"string\");\n  hs.sort((a, b) => (a.presence.since || 0) - (b.presence.since || 0));\n  return hs[0] || null;\n}\nfunction validOrder(order, q){\n  if (!Array.isArray(order) || order.length !== q[4].length) return null;\n  const s = new Set(order);\n  return s.size === order.length && order.every(i => Number.isInteger(i) && i >= 0 && i < q[4].length) ? order : null;\n}\n\n/* ---------- Lobby ---------- */\nfunction renderLobby(){\n  view = \"g-lobby\";\n  if (group && group.code) leaveRoom(true);\n  app.innerHTML = `\n    <div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Estudar em grupo</h3></div></div>\n    <div class=\"panel\">\n      <h2>Estudo em grupo</h2>\n      <p>Uma pessoa cria a sala e vira a líder: ela escolhe o assunto, revela as respostas e passa as questões. Os outros entram com o código. O modo em grupo não mexe no seu progresso individual.</p>\n      <div class=\"field\"><label for=\"gname\">Seu nome na sala</label><input id=\"gname\" maxlength=\"24\" placeholder=\"Ex.: Marco\" value=\"${esc(getName())}\"></div>\n      <div class=\"field\"><label for=\"gcode\">Entrar numa sala</label>\n        <div class=\"row\" style=\"justify-content:flex-start;margin:0\"><input id=\"gcode\" class=\"code\" maxlength=\"4\" placeholder=\"CÓDIGO\" autocomplete=\"off\"><button class=\"primary\" id=\"join\" style=\"width:auto;margin:0\">Entrar</button></div>\n      </div>\n      <div id=\"roomList\"></div>\n      <div class=\"sep\"></div>\n      <div class=\"field\" style=\"margin-bottom:0\"><label>Ou crie uma sala e escolha o assunto</label>\n        <div class=\"topic-pick\">\n          ${Object.keys(TOPICS).map(k => `<button data-t=\"${k}\">${TOPICS[k].name}</button>`).join(\"\")}\n          <button data-t=\"all\">Todos os assuntos</button>\n        </div>\n      </div>\n      <div id=\"gmsg\" aria-live=\"polite\"></div>\n    </div>`;\n  document.getElementById(\"back\").onclick = renderHome;\n  const needName = () => {\n    const n = document.getElementById(\"gname\").value.trim().slice(0, 24);\n    if (!n){ document.getElementById(\"gmsg\").innerHTML = `<div class=\"msg bad\">Coloque seu nome para a turma saber quem é quem.</div>`; document.getElementById(\"gname\").focus(); return null; }\n    setName(n); return n;\n  };\n  document.getElementById(\"join\").onclick = () => {\n    const n = needName(); if (!n) return;\n    const c = cleanCode(document.getElementById(\"gcode\").value);\n    if (c.length !== 4){ document.getElementById(\"gmsg\").innerHTML = `<div class=\"msg bad\">O código tem 4 letras ou números.</div>`; return; }\n    joinRoom(c, n);\n  };\n  document.getElementById(\"gcode\").addEventListener(\"keydown\", e => { if (e.key === \"Enter\") document.getElementById(\"join\").click(); });\n  app.querySelectorAll(\".topic-pick button\").forEach(b => b.onclick = () => { const n = needName(); if (n) createRoom(b.dataset.t, n); });\n  renderRoomList();\n}\n\nfunction renderRoomList(){\n  const el = document.getElementById(\"roomList\");\n  if (!el || !room) return;\n  const hosts = room.peers().filter(p => p.presence && p.presence.app === APP && p.presence.role === \"host\" && typeof p.presence.sala === \"string\" && !p.sameTab);\n  const seen = new Set();\n  const rows = hosts.filter(p => !seen.has(p.presence.sala) && seen.add(p.presence.sala)).map(p => {\n    const code = cleanCode(p.presence.sala);\n    const t = p.presence.topic === \"all\" ? \"Todos os assuntos\" : (TOPICS[p.presence.topic] ? TOPICS[p.presence.topic].name : \"\");\n    return `<div class=\"roomrow\"><span><b>${code}</b> ${esc(p.presence.name || \"Alguém\")}, ${esc(t)}</span><button class=\"ghost\" data-c=\"${code}\" style=\"padding:6px 12px\">Entrar</button></div>`;\n  });\n  el.innerHTML = rows.length ? `<div class=\"field\" style=\"margin:4px 0 0\"><label>Salas abertas agora</label><div class=\"rooms\">${rows.join(\"\")}</div></div>` : \"\";\n  el.querySelectorAll(\"button[data-c]\").forEach(b => b.onclick = () => {\n    const n = document.getElementById(\"gname\").value.trim().slice(0, 24);\n    if (!n){ document.getElementById(\"gmsg\").innerHTML = `<div class=\"msg bad\">Coloque seu nome para entrar.</div>`; return; }\n    setName(n); joinRoom(b.dataset.c, n);\n  });\n}\n\n/* ---------- Criar, entrar, sair ---------- */\nfunction createRoom(topic, name){\n  const pool = shuffle(cardsOf(topic).map(q => q[0]));\n  const q = QUESTIONS.find(x => x[0] === pool[0]);\n  group = { code: newCode(), role: \"host\", name, topic, pool, idx: 0, since: Date.now(), myAns: null };\n  pres({ app: APP, sala: group.code, role: \"host\", name, since: group.since, topic, qid: q[0], order: optionOrder(q), phase: \"q\", ans: null });\n  view = \"g-room\"; renderGroup();\n}\nfunction joinRoom(code, name){\n  group = { code, role: \"member\", name, myAns: null };\n  pres({ app: APP, sala: code, role: \"member\", name, ans: null, since: null, topic: null, qid: null, order: null, phase: null });\n  view = \"g-room\"; renderGroup();\n}\nfunction leaveRoom(silent){\n  pres({ app: null, sala: null, role: null, name: null, since: null, topic: null, qid: null, order: null, phase: null, ans: null });\n  group = null;\n  if (!silent) renderHome();\n}\nfunction takeOver(last){\n  const q = QUESTIONS.find(x => x[0] === last.qid);\n  if (!q) return;\n  const pool = shuffle(cardsOf(last.topic || \"all\").map(x => x[0]).filter(id => id !== q[0]));\n  group.role = \"host\"; group.topic = last.topic || \"all\"; group.pool = [q[0]].concat(pool); group.idx = 0; group.since = Date.now();\n  pres({ role: \"host\", since: group.since, topic: group.topic, qid: q[0], order: validOrder(last.order, q) || optionOrder(q), phase: last.phase === \"rev\" ? \"rev\" : \"q\" });\n}\n\n/* ---------- Ações do líder ---------- */\nfunction hostReveal(){ pres({ phase: \"rev\" }); }\nfunction hostNext(){\n  group.idx++;\n  if (group.idx >= group.pool.length){ group.pool = shuffle(group.pool); group.idx = 0; }\n  const q = QUESTIONS.find(x => x[0] === group.pool[group.idx]);\n  group.myAns = null;\n  pres({ qid: q[0], order: optionOrder(q), phase: \"q\", ans: null });\n}\n\nfunction pickAnswer(qid, i){\n  group.myAns = { q: qid, c: i };\n  pres({ ans: group.myAns });\n  renderGroup();\n}\n\n/* ---------- Tela da sala ---------- */\nfunction renderGroup(){\n  if (!group){ renderHome(); return; }\n  if (roomStatus === \"off\" || !room){\n    app.innerHTML = `<div class=\"topbar\"><button class=\"back\" id=\"back\">Voltar</button><div class=\"t\"><h3>Estudar em grupo</h3></div></div>\n      <div class=\"panel\"><h2>Sem conexão com a sala</h2><p>Não foi possível conectar ao servidor da sala. Confira sua internet e tente de novo.</p></div>`;\n    document.getElementById(\"back\").onclick = () => leaveRoom();\n    return;\n  }\n  const host = hostPeer(group.code);\n  const people = peersInRoom(group.code);\n  const top = `<div class=\"topbar\"><button class=\"back\" id=\"back\">Sair da sala</button>\n      <div class=\"t\"><h3>Estudo em grupo</h3><div>${people.length} ${people.length === 1 ? \"pessoa\" : \"pessoas\"} na sala</div></div></div>\n    <div class=\"gbar\"><span>Código da sala:</span><span class=\"gcode\">${group.code}</span></div>`;\n\n  if (!host){\n    const last = group.lastHost;\n    app.innerHTML = top + `<div class=\"panel\">\n      <h2>${last ? \"O líder saiu da sala\" : \"Procurando a sala...\"}</h2>\n      <p>${last ? \"Alguém precisa assumir para continuar de onde pararam.\" : \"Se demorar, confira o código com quem criou a sala. O líder precisa estar com a página aberta.\"}</p>\n      ${last ? `<button class=\"primary\" id=\"take\">Assumir como líder</button>` : \"\"}\n    </div>`;\n    document.getElementById(\"back\").onclick = () => leaveRoom();\n    const t = document.getElementById(\"take\"); if (t) t.onclick = () => takeOver(last);\n    return;\n  }\n\n  const st = host.presence;\n  group.lastHost = { qid: st.qid, order: st.order, phase: st.phase, topic: st.topic };\n  const q = QUESTIONS.find(x => x[0] === st.qid);\n  if (!q){ app.innerHTML = top + `<div class=\"panel\"><p>Carregando questão...</p></div>`; document.getElementById(\"back\").onclick = () => leaveRoom(); return; }\n  const order = validOrder(st.order, q) || q[4].map((_, i) => i);\n  const revealed = st.phase === \"rev\";\n  const amHost = host.sameTab;\n  if (group.myAns && group.myAns.q !== q[0]) group.myAns = null;\n  const mine = group.myAns ? group.myAns.c : null;\n\n  const answers = {};\n  people.forEach(p => { const a = p.presence.ans; if (a && a.q === q[0] && Number.isInteger(a.c)) answers[p.peer] = a.c; });\n  const answeredCount = Object.keys(answers).length;\n  const chips = people.map(p => {\n    const lead = p.presence.role === \"host\" && p.peer === host.peer;\n    const done = p.peer in answers;\n    return `<span class=\"person${done ? \" done\" : \"\"}${lead ? \" lead\" : \"\"}\"><span class=\"dot\"></span>${esc(p.presence.name || \"Alguém\")}${p.sameTab ? \" (você)\" : \"\"}${lead ? \" · líder\" : \"\"}</span>`;\n  }).join(\"\");\n\n  const opts = order.map((oi, pos) => {\n    let cls = \"opt\";\n    if (revealed){ cls += oi === q[5] ? \" right\" : (oi === mine ? \" wrong\" : \" dim\"); }\n    else if (oi === mine) cls += \" picked\";\n    let who = \"\";\n    if (revealed){\n      const names = people.filter(p => answers[p.peer] === oi).map(p => esc(p.presence.name || \"Alguém\") + (p.sameTab ? \" (você)\" : \"\"));\n      if (names.length) who = `<span class=\"chose\">Marcaram: ${names.join(\", \")}</span>`;\n    }\n    return `<button class=\"opt ${cls.replace(/^opt ?/, \"\")}\" data-i=\"${oi}\" ${revealed ? \"disabled\" : \"\"}><span class=\"l\">${LETTERS[pos]}</span><span>${q[4][oi]}${who}</span></button>`;\n  }).join(\"\");\n\n  const t = TOPICS[st.topic] ? TOPICS[st.topic].name : \"Todos os assuntos\";\n  let fb = \"\";\n  if (revealed){\n    const verdict = mine == null ? `<div class=\"verdict\">Você não respondeu esta.</div>`\n      : mine === q[5] ? `<div class=\"verdict ok\">Você acertou!</div>` : `<div class=\"verdict no\">Você errou. A correta é a ${LETTERS[order.indexOf(q[5])]}.</div>`;\n    fb = `<div class=\"fb\">${verdict}${explainHTML(q, order)}</div>`;\n  }\n  const status = revealed ? \"\" : `<div class=\"gstatus\">${answeredCount} de ${people.length} ${people.length === 1 ? \"respondeu\" : \"responderam\"}${amHost ? \"\" : \". Aguardando o líder revelar a resposta.\"}</div>`;\n  const hostCtl = amHost ? `<div class=\"hostbar\">\n      ${revealed ? `<button class=\"primary\" id=\"next\">Próxima questão</button>` : `<button class=\"primary\" id=\"reveal\">Revelar resposta</button>`}\n      <button class=\"ghost\" id=\"end\">Encerrar sala</button></div>` : \"\";\n\n  app.innerHTML = top + `<div class=\"people\">${chips}</div>\n    <article class=\"qcard\">\n      <div class=\"src\"><span>${q[2]}</span><span class=\"tag\">${esc(t)}</span></div>\n      <p class=\"qtext\">${q[3]}</p>\n      <div class=\"opts\" role=\"group\" aria-label=\"Alternativas\">${opts}</div>\n      ${status}${fb}${hostCtl}\n    </article>`;\n\n  document.getElementById(\"back\").onclick = () => leaveRoom();\n  if (!revealed) app.querySelectorAll(\".opt\").forEach(b => b.onclick = () => pickAnswer(q[0], +b.dataset.i));\n  if (revealed){\n    const saved = session; session = { order };\n    addReasons(q, mine);\n    session = saved;\n  }\n  const r = document.getElementById(\"reveal\"); if (r) r.onclick = hostReveal;\n  const n = document.getElementById(\"next\"); if (n) n.onclick = hostNext;\n  const e = document.getElementById(\"end\"); if (e) e.onclick = () => { if (confirm(\"Encerrar a sala para todo mundo?\")) leaveRoom(); };\n}\n\n/* atalhos de teclado */\ndocument.addEventListener(\"keydown\", e => {\n  if (e.altKey || e.ctrlKey || e.metaKey) return;\n  const tg = e.target && e.target.tagName;\n  if (tg === \"INPUT\" || tg === \"TEXTAREA\") return;\n  if (view !== \"card\" || !session) return;\n  const k = e.key.toLowerCase();\n  if (!session.answered){\n    const idx = [\"a\",\"b\",\"c\",\"d\",\"e\"].indexOf(k);\n    if (idx > -1 && idx < session.order.length){ e.preventDefault(); answer(session.order[idx]); }\n    return;\n  }\n  const cont = document.getElementById(\"cont\");\n  if (cont){ if (k === \"enter\" || k === \" \"){ e.preventDefault(); rate(\"again\"); } return; }\n  if (k === \"1\"){ e.preventDefault(); rate(\"hard\"); }\n  else if (k === \"2\" || k === \"enter\"){ e.preventDefault(); rate(\"good\"); }\n  else if (k === \"3\"){ e.preventDefault(); rate(\"easy\"); }\n});\n\nrenderHome();\n</script>\n</body>\n</html>\n";
